return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Persian','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-06 21:34+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'fa_IR','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'"%1$s %2$s" ذخیره شد.','"%1$s" created. %2$d template updated.'=>'"%1$s" ساخته شد. %2$d قالب به‌روزرسانی شد.' . "\0" . '"%1$s" ساخته شد. %2$d قالب به‌روزرسانی شد.','"%s" created.'=>'"%s" ساخته شد.','"product" (replaces "article")'=>'"محصول" (جایگزین "مقاله")','%1$d chars — good, slightly above the ideal %2$d but within the accepted %3$d-char range. %4$s'=>'٪1$d کاراکتر — خوب، کمی بالاتر از حد ایده‌آل %2$d اما در محدوده مجاز %3$d کاراکتر. %4$s','%1$d chars — ideal length. %2$s'=>'%1$d کاراکتر — طول ایده‌آل. %2$s','%1$d chars — likely truncated in SERPs (keep under %2$d). %3$s'=>'٪1$d کاراکتر — احتمالاً در نتایج جستجو کوتاه شده است (زیر %2$d نگه دارید). %3$s','%1$d chars — too short (aim for %2$d–%3$d). %4$s'=>'%1$d کاراکتر — خیلی کوتاه است (هدف %2$d–%3$d). %4$s','%1$d internal, %2$d external.'=>'d$1٪ داخلی، %2$d خارجی.','%1$d of %2$d image(s) missing alt text.'=>'d$1٪ از %2$d تصویر فاقد متن جایگزین است.','%1$d words — below recommended minimum of %2$d.'=>'%1$d کلمه — کمتر از حداقل توصیه شده %2$d.','%1$d words — very thin content. Consider expanding to at least %2$d words.'=>'%1$d کلمه — محتوای بسیار کم. توسعه آن تا حداقل %2$d کلمه را در نظر بگیرید.','%d chars — good length.'=>'%d کاراکتر — طول مناسب.','%d external link(s), no internal links.'=>'%d پیوند خارجی، بدون پیوند داخلی.','%d external link(s), no internal links. Add internal links to related content.'=>'%d لینک خارجی، بدون لینک داخلی. لینک‌های داخلی به محتوای مرتبط اضافه کنید.','%d H1 tags found — a page should have exactly one H1.'=>'%d برچسب H1 یافت شد — یک صفحه باید دقیقا یک H1 داشته باشد.','%d image(s), all have alt text.'=>'%d تصویر، همه دارای متن جایگزین.','%d language not yet linked'=>'%d زبان هنوز لینک نشده است' . "\0" . '%d زبان هنوز لینک نشده است','%d link updated.'=>'%d لینک به‌روزرسانی شد.' . "\0" . '%d لینک به‌روزرسانی شد.','%d locale file could not be removed automatically (DISALLOW_FILE_MODS is set). Delete it manually via your server or WP-CLI: wp language core uninstall <locale>'=>'٪d فایل زبان قابل حذف خودکار نیست (DISALLOW_FILE_MODS فعال است). آن را به صورت دستی از طریق سرور یا WP-CLI حذف کنید: wp language core uninstall <locale>' . "\0" . '٪d فایل زبان قابل حذف خودکار نیست (DISALLOW_FILE_MODS فعال است). آن‌ها را به صورت دستی از طریق سرور یا WP-CLI حذف کنید: wp language core uninstall <locale>','%d locale file removed.'=>'٪d فایل زبان حذف شد.' . "\0" . '٪d فایل زبان حذف شد.','%d locale pack installed.'=>'%d بسته محلی نصب شده است.' . "\0" . '%d بسته محلی نصب شده است.','%d navigation reference updated.'=>'%d ارجاع ناوبری به‌روزرسانی شد.' . "\0" . '%d ارجاعات ناوبری به‌روزرسانی شد.','%d part reference updated.'=>'%d ارجاع قسمت به‌روزرسانی شد.' . "\0" . '%d ارجاعات قسمت به‌روزرسانی شد.','%d words.'=>'%d کلمه.','%s Archive'=>'%s آرشیو','%s is active and already outputs Schema.org JSON-LD. Lingua Forge has disabled its own schema output to prevent conflicting graphs. Unlike Open Graph — where LF adds og:locale on top of another plugin\'s output — schema cannot be cleanly supplemented: duplicate or overlapping JSON-LD graphs produce validation errors. Disable schema output in the detected plugin if you want LF to handle structured data.'=>'%s فعال است و در حال حاضر JSON-LD Schema.org را خروجی می‌دهد. Lingua Forge خروجی schema خود را غیرفعال کرده است تا از تداخل گراف‌ها جلوگیری کند. بر خلاف Open Graph — که LF og:locale را بر روی خروجی پلاگین دیگری اضافه می‌کند — schema نمی‌تواند به صورت تمیز تکمیل شود: گراف‌های JSON-LD تکراری یا همپوشان خطاهای اعتبارسنجی ایجاد می‌کنند. اگر می‌خواهید LF داده‌های ساختاریافته را مدیریت کند، خروجی schema در پلاگین شناسایی شده را غیرفعال کنید.','%s is active and generates its own sitemap. That sitemap is separate from LF\'s. Both should be submitted to Google Search Console: the SEO plugin sitemap lists your content; the LF sitemap adds the multilingual alternate links. LF\'s sitemap is announced in robots.txt automatically.'=>'%s فعال است و سایت‌نقشه مخصوص خود را تولید می‌کند. آن سایت‌نقشه جدا از LF است. هر دو باید به کنسول جستجوی گوگل ارسال شوند: سایت‌نقشه پلاگین سئو محتوای شما را فهرست می‌کند؛ سایت‌نقشه LF لینک‌های جایگزین چندزبانه را اضافه می‌کند. سایت‌نقشه LF به طور خودکار در robots.txt اعلام می‌شود.','(avg %.1f hits/block)'=>'(متوسط %.1f ضربه/بلوک)','(avg %.1f hits/entry)'=>'(میانگین %.1f ضربه/ورودی) ','(disabled)'=>'(غیرفعال شده)','(no title) #%d'=>'(بدون عنوان) #%d','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} هیچ لینک قابل جایگزینی نداشت — برای بررسی مجدد اسکن کنید)','.txt file(s) in the directory'=>'.txt فایل(ها) در دایرکتوری','/ 100'=>'/ 100','1 H1 ✓ — no H2 subheadings (acceptable for this content type).'=>'۱ H1 ✓ — بدون زیرعنوان H2 (مورد قبول برای این نوع محتوا).','1 H1 ✓ — no H2 subheadings found. Adding H2s improves structure.'=>'۱ H1 ✓ — هیچ زیرعنوان H2 یافت نشد. افزودن H2 ساختار را بهبود می‌بخشد.','1 H1 ✓, %1$d H2, %2$d H3.'=>'۱ H1 ✓، ٪1$d H2، ٪2$d H3.','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d قالب محلی‌شده(های) %2$s از قالب «%2$s» در پایگاه داده نگهداری می‌شود اما در حال حاضر غیرفعال است. اگر آن قالب را فعال مجدد کنید، دوباره فعال می‌شود. برای انتقال ترجمه‌های خود به قالب جدید، آنها را از طریق <strong>تنظیمات → Lingua Forge → مسیریاب → اسکافولد FSE</strong> بازتولید کنید.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> لینک قابل اصلاح خودکار','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> لینک نیازمند بازبینی دستی','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> مسیر منقضی شده','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> مشکل قالب','A physical robots.txt file exists at the site root. WordPress\'s virtual robots.txt — and LF\'s Sitemap: filter — are bypassed. The LF sitemap is not announced to search engines.'=>'یک فایل robots.txt فیزیکی در ریشه سایت وجود دارد. robots.txt مجازی وردپرس — و فیلتر Sitemap در LF — نادیده گرفته می‌شود. سایت‌نقشه LF به موتورهای جستجو اعلام نمی‌شود.','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'فقط فایل‌های کامپایل شده .mo را می‌پذیرد. نام فایل باید مطابق با الگو {textdomain}-{locale}.mo باشد. آپلود فایلی با همان نام فایل موجود جایگزین می‌شود.','Action'=>'عمل','Actions'=>'اقدامات','active'=>'فعال','Active Languages'=>'زبان‌های فعال','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'زبان‌های فعال: هر زبانی را که می‌خواهید پشتیبانی کنید، اضافه کنید. هر زبان یک پیشوند URL یا زیر دامنه دریافت می‌کند و یک برچسب hreflang در بخش &lt;head&gt; صفحه دارد.','Active Provider'=>'ارائه‌دهنده فعال','Add entry'=>'اضافه کردن ورودی','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'دستورالعمل‌هایی برای بهبود پیش‌نویس اضافه کنید — مثلا کوتاه‌تر کردن، افزودن بخش نتیجه‌گیری، استفاده از زبان رسمی‌تر، افزودن بخش سوالات متداول…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'دستورالعمل‌هایی برای بهبود پیش‌نویس اضافه کنید — مثلاً کوتاه‌تر کردن، افزودن بخش نتیجه‌گیری، استفاده از لحن رسمی‌تر…','Add new entry'=>'ورودی جدید اضافه کنید','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'یک اصطلاح در هر ردیف اضافه کنید. هر دو اصطلاح منبع و ترجمه هدف لازم است. زوج زبان تعیین می‌کند که کدام وظایف ترجمه این محدودیت را دارند.','Add Sitemap directive to robots.txt'=>'افزودن دستور Sitemap به robots.txt','Add the following line to your robots.txt manually:'=>'خط زیر را به صورت دستی به robots.txt خود اضافه کنید:','Add WooCommerce product tags to Open Graph output'=>'افزودن برچسب‌های محصول ووکامرس به خروجی Open Graph','Adds a link to the home page so visitors can browse in their language.'=>'یک لینک به صفحه اصلی اضافه می‌کند تا بازدیدکنندگان بتوانند در زبان خود مرور کنند.','Administrators only (manage_options)'=>'فقط مدیران (manage_options)','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'پس از تغییر زبان اصلی، پیوندهای یکتا (بخش زیر) را برای به‌روزرسانی مسیر URL پاک‌سازی کنید.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'پس از تغییر تنظیمات ساختار URL (پیشوند مسیر ↔ زیر دامنه)، همیشه به تنظیمات → پیوندهای یکتا مراجعه کنید و روی ذخیره تغییرات کلیک کنید تا قوانین بازنویسی پاک شوند.','AI analysis failed. Please try again.'=>'تحلیل AI ناموفق بود. لطفاً دوباره تلاش کنید.','AI Behaviour Preset'=>'پیش‌فرض رفتار هوش مصنوعی','AI cache cleared. %d entry was removed.'=>'کش هوش مصنوعی پاک شد. %d ورودی حذف شد.' . "\0" . 'کش هوش مصنوعی پاک شد. %d ورودی حذف شدند.','AI Cache: lists cached AI responses with hit counts. Clear the whole cache or a single post\'s entries. Use "Clear" before testing a translation change — cached results are returned even when you change the AI preset or model until the cache entry is evicted.'=>'کش هوش مصنوعی: فهرستی از پاسخ‌های کش شده هوش مصنوعی با تعداد ضربه‌ها. کل کش یا ورودی‌های یک پست خاص را پاک کنید. قبل از آزمایش تغییر ترجمه، "پاک کردن" را استفاده کنید — نتایج کش شده حتی زمانی که پیش‌تنظیم یا مدل هوش مصنوعی را تغییر می‌دهید، برگردانده می‌شوند تا زمانی که ورودی کش حذف شود.','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'ویژگی‌های هوش مصنوعی اختیاری هستند. مسیریابی زبان، hreflang، سوئیچر زبان، و سیستم گروه ترجمه همگی بدون پیکربندی ارائه‌دهنده کار می‌کنند.','AI Limits & Security'=>'محدودیت‌ها و امنیت هوش مصنوعی','AI provider returned an empty response.'=>'پروایدر هوش مصنوعی پاسخ خالی برگرداند.','AI Recommendations'=>'پیشنهادات AI','AI returned an unexpected response format. Please try again.'=>'AI پاسخ غیرمنتظره‌ای برگرداند. لطفاً دوباره تلاش کنید.','AI Usage'=>'استفاده از هوش مصنوعی','AI Usage & Cache'=>'استفاده و کش AI','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'هدف 120–160 کاراکتر است. برای استفاده از جایگزین چکیده، خالی بگذارید.','All major search engines — Google, Bing, and Yandex — discover the sitemap automatically via the Sitemap: directive in robots.txt. No manual action is required. The buttons below send an immediate ping so the engine recrawls the sitemap now rather than waiting for its next scheduled robots.txt check.'=>'تمام موتورهای جستجو اصلی — گوگل، بینگ و یاندکس — سایت‌نقشه را به طور خودکار از طریق دستور Sitemap در robots.txt کشف می‌کنند. نیاز به اقدام دستی نیست. دکمه‌های زیر یک پینگ فوری ارسال می‌کنند تا موتور سایت‌نقشه را اکنون مجدداً کراول کند، نه منتظر بررسی بعدی robots.txt.','All time'=>'همه زمان‌ها','All types'=>'همه نوع‌ها','Allow editors to lock individual blocks'=>'اجازه دهید ویرایشگران بلوک‌های جداگانه را قفل کنند','Allow Gutenberg template-editing mode on post screens'=>'اجازه دهید حالت ویرایش قالب Gutenberg در صفحات پست فعال شود','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'همچنین تخصیص‌های زبان، روابط ترجمه، توضیحات متا، واژه‌نامه و حافظه ترجمه هنگام حذف افزونه حذف می‌شوند.','Also generate meta description'=>'همچنین توضیف متا را تولید کنید','Alternative (server-side):'=>'جایگزین (در سمت سرور):','Always emit only og:locale and og:locale:alternate. Use when another plugin or theme handles the full OG set.'=>'همیشه فقط og:locale و og:locale:alternate را صادر کنید. زمانی که پلاگین یا قالب دیگری مجموعه کامل OG را مدیریت می‌کند، استفاده شود.','Always emit the complete OG + Twitter Card set regardless of other plugins. Use only if no other plugin outputs OG tags.'=>'همیشه مجموعه کامل OG + کارت توییتر را صادر کنید، صرف نظر از پلاگین‌های دیگر. فقط در صورتی استفاده کنید که پلاگین دیگری برچسب‌های OG را خروجی ندهد.','An unknown error occurred.'=>'خطای ناشناخته‌ای رخ داد.','Analyse…'=>'تحلیل…','Analysis'=>'تحلیل','Analysis request failed. Please try again.'=>'درخواست تحلیل ناموفق بود. لطفاً دوباره تلاش کنید.','Analyzing…'=>'در حال تحلیل…','and'=>'و','Anthropic (Claude)'=>'آنتروپیک (کلود)','any'=>'هر','API calls saved by cache'=>'درخواست‌های API ذخیره شده در کش','API Key'=>'کلید API','API Keys'=>'کلیدهای API','API Keys Tab'=>'تب کلیدهای API','API Response Cache'=>'کش پاسخ‌های API','Appends the following line to your existing robots.txt: %s'=>'خط زیر را به فایل robots.txt موجود خود اضافه می‌کند: %s','Applied ✓'=>'تایید شده ✓','Apply failed — please try again.'=>'درخواست اجرا نشد — لطفاً دوباره تلاش کنید.','Apply to Block'=>'اعمال به بلوک','Apply to Editor'=>'اعمال در ویرایشگر','Apply to Footnote'=>'اعمال به پاورقی','Apply to Meta Description'=>'اعمال به توضیحات متا','Apply translation'=>'اعمال ترجمه','Applying…'=>'در حال اعمال…','Approximate size'=>'اندازه تقریبی','Archive'=>'آرشیو','Archive: %s'=>'آرشیو: %s','Article / WebPage'=>'مقاله / صفحه وب','Article / WebPage — all singular posts and pages'=>'مقاله / صفحه وب — تمام پست‌ها و صفحات مفرد','Authors and above (edit_published_posts)'=>'نویسندگان و بالاتر (edit_published_posts)','Auto (recommended)'=>'خودکار (توصیه شده)','Behavior'=>'رفتار','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'رفتار: پیش‌تنظیم هوش مصنوعی را انتخاب کنید (مطلق، متعادل، خلاق)، دستورالعمل‌های سفارشی سایت را اضافه کنید، ترجمه خودکار پس از ذخیره پست را فعال یا غیرفعال کنید، و حافظه ترجمه را پیکربندی کنید.','Block Content'=>'محتوای بلوک','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'در صورت عدم وجود ترجمه برای زبان بازدیدکننده، اطلاعیه مودبانه‌ای نشان داده می‌شود که صفحه در زبان منبع خود نمایش داده می‌شود. این بر اساس سیگنال LINGUAFORGE_LANG_FALLBACK_ACTIVE روتر لینگو فورج است — وقتی ترجمه‌ای برای منطقه درخواست وجود دارد، چیزی منتشر نمی‌کند.','Block Editor'=>'ویرایشگر بلوک','block keywordfallback'=>'پشتوانه','block keywordi18n'=>'بین‌المللی‌سازی','block keywordlanguage'=>'زبان','block keywordlinguaforge'=>'لینگوا فورج','block keywordtranslation'=>'ترجمه','Block locking'=>'قفل کردن بلوک','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'الگوهای بلوک ثبت شده برای نوع‌های پست سفارشی. از دکمه ترجمه برای تولید نسخه زبانی استفاده کنید. محتوای ترجمه شده در اینجا ذخیره می‌شود و می‌توان آن را از واردکننده الگوی ویرایشگر بلوک یا به عنوان نقطه شروع برای الگوی همگام‌سازی شده (بلوک قابل استفاده مجدد) کپی کرد.','block titleMissing Translation Notice'=>'اطلاعیه ترجمه مفقود','Block translation reuses'=>'استفاده مجدد ترجمه بلوک‌ها','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Configure in Settings → Behavior.'=>'کش ترجمه بلوک در سطح بلوک که در سراسر پست‌ها مشترک است. زمانی که فعال باشد، بلوک‌های یکسان (با همان نشانه‌گذاری، زوج زبان، و واژه‌نامه) از حافظه سرو می‌شوند به جای فراخوانی مجدد هوش مصنوعی. در تنظیمات → رفتار پیکربندی کنید.','Blog / Editorial'=>'وبلاگ / تحریریه','Blog posts use Article; all other post types and pages use WebPage. Includes headline, description, inLanguage, url, datePublished, dateModified, image, and publisher.'=>'پست‌های وبلاگ از مقاله استفاده می‌کنند؛ سایر نوع‌های پست و صفحات از صفحه وب. شامل عنوان، توضیحات، inLanguage، url، تاریخ انتشار، تاریخ ویرایش، تصویر و ناشر.','Browser language redirect'=>'انتقال زبان مرورگر','Built-in preset instructions:'=>'دستورالعمل‌های پیش‌فرض داخلی:','Bulletize (•-prefixed)'=>'لیست‌گذاری (با •-پیشوند)','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'ذخیره ترجمه‌های معادل در سطح بلوک تا محتوای قابل استفاده مجدد (پاورقی‌های مشترک، نوار کناری، آکاردئون‌ها، بخش‌های حقوقی پر از قالب) هر بار هزینه تماس API نداشته باشد. زمانی که فعال است، جریان ترجمه هر پست را به بلوک‌ها تجزیه می‌کند، هر بلوک را در کش جستجو می‌کند و تنها بلوک‌های غیرکش شده را در یک درخواست دسته‌ای به هوش مصنوعی می‌فرستد. ویرایش‌های واژگان و تغییرات پیش‌فرض تطابق به طور خودکار کش ترجمه‌های تحت تاثیر را بی‌اعتبار می‌کند. آمار را مشاهده کنید و کش را در بخش نگهداری پاک کنید.','cached'=>'در حافظه کش','Cached API responses'=>'پاسخ‌های API کش شده','Cached block translations'=>'ترجمه‌های بلوک کش شده','Cancel'=>'لغو','Cannot determine target language from slug.'=>'نمی‌توان زبان هدف را از slug تشخیص داد.','Cannot write to product %1$d: it is a translated version (language: %2$s)%3$s. Operational data (price, stock, SKU, dimensions) must be updated on the source product. Resolve the source product ID via: GET /wp-json/lingua-forge/v1/post/%4$d/translations'=>'نمی‌توان به محصول %1$d نوشت؛ این نسخه ترجمه شده است (زبان: %2$s)%3$s. داده‌های عملیاتی (قیمت، موجودی، SKU، ابعاد) باید در محصول منبع به‌روزرسانی شوند. شناسه محصول منبع را از طریق: GET /wp-json/lingua-forge/v1/post/%4$d/translations حل کنید.','Canonical tag'=>'تگ canonical','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'محدود کردن میزان استفاده از هوش مصنوعی که سایت می‌تواند تولید کند و محدود کردن نقش‌های کاربری که می‌توانند تماس‌های پولی هوش مصنوعی را فعال کنند. این محدودیت بر روی محدودیت نرخ هر کاربر (30 درخواست / دقیقه، سخت‌کد شده) که قبلاً در برابر حلقه‌های بی‌پایان کاربر منفرد محافظت می‌کند، قرار دارد.','chars'=>'کاراکترها','Chunk translated'=>'بخش ترجمه شده','Chunk translated to:'=>'بخش ترجمه شده به:','Clear'=>'پاک کردن','Clear All'=>'پاک کردن همه','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'آیا می‌خواهید تمام نتایج کش شده هوش مصنوعی را پاک کنید؟ درخواست‌های آینده تا زمانی که کش مجدداً ساخته شود، درخواست‌های جدید را فعال می‌کنند.','Clear API Response Cache'=>'پاک کردن کش پاسخ‌های API','Clear Debug Files'=>'پاک‌سازی فایل‌های اشکال‌زدایی','Clear hints'=>'پاک کردن راهنماها','Clear input'=>'پاک کردن ورودی','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'آیا می‌خواهید حافظه ترجمه را کاملاً پاک کنید؟ ترجمه‌های آینده کش را مجدداً می‌سازد.','Clear Translation Memory'=>'پاک‌سازی حافظه ترجمه','Close'=>'بستن','Close language panel'=>'بستن پنل زبان','Close popover'=>'بستن پنجره','Compatibility'=>'سازگاری','Compliance Preset'=>'پیش‌فرض تطابق','Configure an AI provider in Settings → API Keys to enable AI-powered recommendations.'=>'در تنظیمات → کلیدهای API، یک ارائه‌دهنده AI پیکربندی کنید تا پیشنهادات مبتنی بر AI فعال شود.','Content generated'=>'محتوا تولید شده','Content Generator'=>'تولیدکننده محتوا','Content ready'=>'محتوا آماده است','Contributors and above — default (edit_posts)'=>'همه مشارکت‌کنندگان و بالاتر — پیش‌فرض (edit_posts)','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'کنترل میزان محتوایی که به هوش مصنوعی ارسال می‌شود و اندازه پاسخ می‌تواند باشد. برای استفاده از مقدار پیش‌فرض داخلی، فیلد را خالی بگذارید. این مقادیر را افزایش دهید اگر صفحات بزرگ قطع می‌شوند؛ آنها را کاهش دهید تا هزینه‌های API کاهش یابد.','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'کنترل بودجه توکن و محدودیت‌های ورودی برای ویژگی تولید محتوای هوش مصنوعی. برای استفاده از مقادیر پیش‌فرض داخلی، فیلدها را خالی بگذارید.','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'کنترل می‌کند چه زمانی وقتی مدیر افزونه را از مسیر افزونه‌ها → افزونه‌های نصب‌شده → حذف می‌کند، اتفاق می‌افتد. تنظیمات افزونه و کش‌های هوش مصنوعی همیشه حذف می‌شوند. تخصیص‌های زبان و روابط ترجمه به طور پیش‌فرض نگه داشته می‌شوند تا حذف تصادفی یا نصب مجدد بتواند ادامه دهد.','Conversational'=>'گفتگو محور','Copied ✓'=>'کپی شد ✓','Copy'=>'کپی','Copy failed — please copy the URL manually.'=>'کپی ناموفق بود — لطفاً URL را به صورت دستی کپی کنید.','Copy markup'=>'کپی کردن قالب‌بندی','Copy the current URL to the clipboard. Shows a "Link copied" toast on success.'=>'آدرس فعلی را در کلیپ‌بورد کپی کنید. در صورت موفقیت، پیام "لینک کپی شد" نشان داده می‌شود.','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'نتیجه را کپی کنید و هرجا نیاز است جایگذاری کنید (مثلاً مستقیماً در فیلد پانوشت).','Copy to safe storage'=>'کپی به ذخیره‌سازی امن','copy/native/auto JS actions: handled by LF\'s social-share.js'=>'اقدامات JS کپی/بومی/خودکار: توسط social-share.js LF مدیریت می‌شود','Could not add entry: source term and target term are required.'=>'امکان افزودن ورودی وجود ندارد: اصطلاح منبع و اصطلاح هدف الزامی است.','Could not copy the file. Check that the uploads folder is writable.'=>'نمی‌توان فایل را کپی کرد. بررسی کنید که پوشه آپلود قابل نوشتن است.','Could not instantiate the provider.'=>'نمی‌توان ارائه‌دهنده را نمونه‌سازی کرد.','Could not save the file. Check that the uploads folder is writable.'=>'نمی‌توان فایل را ذخیره کرد. بررسی کنید که پوشه آپلود قابل نوشتن است.','Could not save the glossary entry.'=>'امکان ذخیره‌سازی ورودی واژگان وجود ندارد.','Could not write to robots.txt. Check file permissions.'=>'امکان نوشتن در robots.txt وجود ندارد. مجوزهای فایل را بررسی کنید.','CPT Block Patterns'=>'الگوهای بلوک CPT','Create'=>'ایجاد','Create missing'=>'ایجاد موارد گمشده','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'ایجاد ترجمه برای نوع پست "%s" نیازمند یکپارچه‌سازی فعال است. لطفاً اطمینان حاصل کنید که یکپارچه‌سازی مورد نیاز نصب و فعال است.','Creating…'=>'در حال ایجاد…','Creative / Marketing'=>'خلاقانه / بازاریابی','Creative / Marketing instructions'=>'دستورالعمل‌های خلاقانه / بازاریابی','Current content (will be overwritten)'=>'محتوای فعلی (بازنویسی می‌شود)','Current status'=>'وضعیت فعلی','Current title'=>'عنوان فعلی','Current: {current}'=>'در حال حاضر: {current}','Currently emitting'=>'در حال انتشار','Currently inherited from the %s constant. Selecting a value here will override it.'=>'در حال حاضر از ثابت %s ارث‌بری شده است. انتخاب یک مقدار در اینجا آن را جایگزین می‌کند.','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'در حال حاضر برای پست‌هایی که از جای‌گذاری‌های بلوک-کامنت (wp:details فیلدهای خلاصه و غیره) استفاده می‌کنند، نادیده گرفته می‌شود — آن‌ها به مسیر ترجمه یک‌درخواست موجود می‌افتند.','Currently:'=>'در حال حاضر:','Custom'=>'سفارشی','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'سهم روزانه هوش مصنوعی پر شده است (%1$d درخواست). در ساعت %2$s به وقت UTC مجدداً تنظیم می‌شود.','Daily request limit'=>'محدودیت درخواست روزانه','Danger Zone'=>'منطقه خطر','Debug Files'=>'فایل‌های اشکال‌زدایی','Debug files cleared. %d file was removed.'=>'فایل‌های اشکال‌زدایی پاک شدند. %d فایل حذف شد.' . "\0" . 'فایل‌های اشکال‌زدایی پاک شدند. %d فایل حذف شدند.','Debug logging'=>'لاگ‌گیری اشکال‌زدایی','Debug logging disabled.'=>'لاگ‌گیری اشکال‌زدایی غیرفعال شد.','Debug logging enabled.'=>'لاگ‌گیری اشکال‌زدایی فعال شد.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'اشکال‌زدایی: فعال کردن لاگ اشکال‌زدایی برای ضبط درخواست‌های هوش مصنوعی و پاسخ‌های API در یک فایل محلی. پس از رفع اشکال غیرفعال کنید — حالت اشکال‌زدایی فایلی در هر درخواست هوش مصنوعی می‌نویسد.','Default OG image'=>'تصویر OG پیش‌فرض','Delete'=>'حذف','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'آیا می‌خواهید تمام فایل‌های .txt در دایرکتوری اشکال‌زدایی را حذف کنید؟ خود دایرکتوری باقی می‌ماند تا نوشته‌های اشکال‌زدایی آینده به آن وارد شوند.','Delete all files for this override (both .mo and .po)?'=>'حذف تمام فایل‌های این جایگزینی (هر دو فایل .mo و .po)؟','Delete content data on uninstall'=>'حذف داده‌های محتوا هنگام حذف','Delete this glossary entry?'=>'آیا می‌خواهید این ورودی واژگان را حذف کنید؟','Describe what to write — topic, key points, structure…'=>'توصیف آنچه باید نوشته شود — موضوع، نکات کلیدی، ساختار…','Details ↗'=>'جزئیات ↗','Detect active SEO plugins (Yoast, Rank Math, etc.) at runtime. Emit only og:locale + og:locale:alternate when another plugin already outputs the full OG set; emit the complete set when none is detected.'=>'تشخیص پلاگین‌های فعال SEO (Yoast، Rank Math و غیره) در زمان اجرا. فقط og:locale + og:locale:alternate را زمانی که پلاگین دیگری مجموعه کامل OG را خروجی می‌دهد، منتشر کنید؛ زمانی که هیچ پلاگینی تشخیص داده نشود، مجموعه کامل را منتشر کنید.','Directory'=>'دایرکتوری','Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them. Increasing API spend immediately on busy sites is expected when disabled.'=>'در حین تنظیم پارامترهای درخواست یا زمانی که نیاز دارید هر درخواست به ارائه‌دهنده هوش مصنوعی برسد، غیرفعال کنید. غیرفعال کردن ورودی‌های کش شده را حذف نمی‌کند — فعال‌سازی مجدد آن‌ها را بازیابی می‌کند. افزایش هزینه API بلافاصله در سایت‌های پرترافیک هنگام غیرفعال بودن انتظار می‌رود.','Disable only for headless sites or fully custom hreflang implementations. When disabled, LF no longer removes the WordPress core canonical tag and no longer suppresses SEO-plugin hreflang output.'=>'فقط برای سایت‌های بدون سر یا پیاده‌سازی‌های کاملاً سفارشی hreflang غیرفعال کنید. زمانی که غیرفعال است، LF دیگر تگ canonical هسته وردپرس را حذف نمی‌کند و خروجی hreflang پلاگین SEO را نیز سرکوب نمی‌کند.','Disabled'=>'غیرفعال شده','Disabled (by setting)'=>'غیرفعال شده (با تنظیمات)','Disabled (mode setting)'=>'غیرفعال شده (در حالت تنظیمات)','Disabled because the lf-social-share mu-plugin is already providing this feature.'=>'به دلیل اینکه پلاگین mu-social-share LF در حال حاضر این ویژگی را فراهم می‌کند، غیرفعال است.','DISALLOW_FILE_MODS is set.'=>'DISALLOW_FILE_MODS تنظیم شده است.','Display'=>'نمایش','Displays the Lingua Forge language switcher.'=>'نمایش سوئیچ زبان لینگوآ فورج.','Do not output any OG tags.'=>'هیچ تگ OG را خروجی ندهید.','Documentation'=>'مستندات','Done'=>'تمام شد','Done — {done} of {total} post(s) fixed.'=>'انجام شد — {done} از {total} پست اصلاح شد.','Down'=>'پایین','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'یک بسته زبان وردپرس را مستقیماً از WordPress.org دانلود و نصب کنید. پس از نصب، زبان محلی برای مسیر یابی URL و روند ترجمه هوش مصنوعی در دسترس قرار می‌گیرد. فهرست زبان‌های در دسترس بر اساس نیاز بارگیری می‌شود — برای بارگذاری آن، روی دکمه زیر کلیک کنید.','Dropdown direction'=>'جهت منوی کشویی','edit'=>'ویرایش','Editors and above (edit_others_posts)'=>'ویرایشگران و بالاتر (edit_others_posts)','Enable API response caching'=>'فعال کردن کش پاسخ‌های API','Enable block-level translation cache reuse across posts'=>'استفاده مجدد از کش ترجمه در سطح بلوک در سراسر پست‌ها','Enable Social Share URL rewriting for Social Icons blocks'=>'فعال‌سازی بازنویسی URL اشتراک‌گذاری اجتماعی برای بلوک‌های آیکون‌های اجتماعی','Enable when your theme renders the post title as an H2 instead of an H1 (common in some block themes). The analyser fetches the rendered page and, if it finds no H1 but does find an H2, it promotes the first H2 to H1 for scoring purposes.'=>'فعال کنید زمانی که قالب شما عنوان پست را به عنوان H2 به جای H1 نمایش می‌دهد (در برخی قالب‌های بلوک رایج است). تحلیلگر صفحه رندر شده را می‌گیرد و اگر H1 پیدا نکند اما H2 بیابد، اولین H2 را به H1 برای امتیازدهی ارتقاء می‌دهد.','Enter your API key for at least one AI provider. Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'کلید API خود را برای حداقل یک ارائه‌دهنده هوش مصنوعی وارد کنید. کلیدها با استفاده از AES-256-GCM و یک راز مخصوص سایت (LINGUAFORGE_SECRET) در حالت استراحت رمزگذاری می‌شوند. بدون چرخاندن راز، صادرات پایگاه داده را به اشتراک نگذارید.','environment variable'=>'متغیر محیطی','Error'=>'خطا','Expand'=>'گسترش دادن','Expected: {expected}'=>'انتظار می‌رفت: {expected}','External share services'=>'سرویس‌های اشتراک‌گذاری خارجی','Extra guidance — tone, style, constraints, target audience…'=>'راهنمایی اضافی — لحن، سبک، محدودیت‌ها، مخاطب هدف…','Extra guidance — tone, style, constraints…'=>'راهنمایی اضافی — لحن، سبک، محدودیت‌ها…','Failed. Please try again.'=>'ناموفق. لطفاً دوباره تلاش کنید.','Fallback image URL used when a page has no featured image, site logo, or site icon. Shown in social previews for archives, the blog index, and any singular page without a thumbnail.'=>'آدرس تصویر جایگزین زمانی که صفحه تصویر شاخص، لوگوی سایت یا آیکون سایت ندارد. در پیش‌نمایش‌های اجتماعی برای آرشیوها، فهرست وبلاگ و هر صفحه تکی بدون تصویر بندانگشتی نشان داده می‌شود.','Feature'=>'ویژگی','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'ویژگی‌ها در دو سطح گروه‌بندی شده‌اند. شناسه مدل دقیق برای هر سطح و ارائه‌دهنده وارد کنید. برای استفاده از مقدار پیش‌فرض داخلی، فیلد را خالی بگذارید (به عنوان جای‌گذاری نشان داده شده است). تنها مدل‌های ارائه‌دهنده فعال در زمان اجرا فراخوانی می‌شوند — دیگران را در صورت نیاز قبل از تغییر پیکربندی کنید.','File copied to safe storage successfully.'=>'فایل با موفقیت به ذخیره‌سازی امن کپی شد.','File modifications are disabled (DISALLOW_FILE_MODS).'=>'تغییرات فایل غیرفعال شده است (DISALLOW_FILE_MODS).','Files'=>'فایل‌ها','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'فایل‌ها در دایرکتوری زیر قرار می‌گیرند. مفید برای تشخیص مشکلات ترجمه — پس از دریافت نیاز، آن را خاموش کنید تا فایل‌ها تجمع نکنند. همچنین می‌توانید این کار را از wp-config.php با `define( \'LINGUAFORGE_AI_DEBUG\', true );` انجام دهید که این سوئیچ را لغو می‌کند.','Filter'=>'فیلتر','Filter by language and post type, browse your content, and click Analyze on any item to run a rule-based SEO audit — title length, meta description, word count, heading structure, image alt coverage, and internal links.'=>'فیلتر بر اساس زبان و نوع پست، محتوای خود را مرور کنید و بر روی هر مورد کلیک کنید تا ارزیابی SEO مبتنی بر قانون را اجرا کنید — طول عنوان، توضیحات متا، تعداد کلمات، ساختار عنوان، پوشش متن جایگزین تصویر و لینک‌های داخلی.','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'با فیلتر linguaforge_debug_dir برای هدایت خروجی اشکال‌زدایی به مکان غیر عمومی استفاده کنید.','Finding'=>'در حال پیدا کردن','Fix'=>'اصلاح','Fix All'=>'همه را اصلاح کن','Fix all links'=>'رفع مشکل تمام لینک‌ها','Fix all parts'=>'رفع مشکل تمام قسمت‌ها','Fix Links'=>'رفع اشکال لینک‌ها','Fix Nav'=>'رفع اشکال ناوبری','Fix Parts'=>'رفع اشکال قسمت‌ها','Fix Template'=>'رفع مشکل قالب','Fixing {n} / {total}…'=>'در حال اصلاح {n} / {total}…','Fixing…'=>'در حال اصلاح…','Flush Permalink Rules'=>'تازه‌سازی قوانین پیوند یکتا','Flush Permalinks'=>'تازه‌سازی پیوندهای یکتا','Flush Sitemap Cache'=>'پاک‌سازی کش سایت‌مپ','Footnote Content'=>'محتوای پاورقی','footnote(s) translated — applied together with content.'=>'پانوشت(ها) ترجمه شده — همراه با محتوا اعمال شد.','Footnotes'=>'پانوشت‌ها','Footnotes payload (advanced)'=>'بارگذاری پاورقی‌ها (پیشرفته)','Forbidden'=>'ممنوع','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'به صورت اجباری توسط ثابت LINGUAFORGE_AI_DEBUG در wp-config.php غیرفعال شده است. برای کنترل این سوئیچ از اینجا، آن خط را حذف کنید.','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'به صورت اجباری توسط ثابت LINGUAFORGE_AI_DEBUG در wp-config.php فعال شده است. برای کنترل این سوئیچ از اینجا، آن خط را حذف کنید.','Forces the sitemap to regenerate on the next request. Use after bulk-importing or manually editing translation relationships.'=>'سایت‌مپ را مجبور می‌کند در درخواست بعدی بازتولید شود. پس از وارد کردن دسته‌جمعی یا ویرایش دستی روابط ترجمه، استفاده کنید.','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'در {parts} در میان <strong>{total}</strong> پست اسکن شده در <strong>{scanned}</strong> برای <strong>{lang}</strong> پیدا شد.','From'=>'از','Front Page'=>'صفحه اصلی','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'محلی‌سازی FSE: اسکافولد، ترجمه، و اصلاح لینک‌ها در قالب‌ها و قسمت‌های قالب کامل سایت مستقیماً از این برگه.','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'قالب‌های FSE از قالب فعال ساخته شده است. در ویرایشگر سایت ایجاد و سفارشی کنید.','Full'=>'کامل','Full Article'=>'مقاله کامل','Full post'=>'پست کامل','General'=>'عمومی','Generate'=>'تولید','Generate Content'=>'تولید محتوا','Generate content…'=>'در حال تولید محتوا…','Generate Excerpt'=>'ایجاد گزیده','Generate Meta Description'=>'ایجاد توضیف متا','Generate the multilingual sitemap at /lf-sitemap.xml'=>'ایجاد سایت‌مپ چندزبانه در /lf-sitemap.xml','Generated Content'=>'محتوای تولید شده','Generated meta description'=>'توضیحات متا تولید شده','Generating…'=>'در حال تولید…','Generation failed.'=>'تولید ناموفق بود.','Getting started'=>'شروع کار','Global AI preset'=>'پیش‌فرض هوش مصنوعی جهانی','Global default (%s)'=>'پیش‌فرض جهانی (%s)','Glossary'=>'واژه‌نامه','Glossary entry added.'=>'ورود واژگان اضافه شد.','Glossary entry removed.'=>'ورود واژگان حذف شد.','Glossary Tab'=>'تب واژگان','Google (Gemini)'=>'گوگل (جمینی)','H2-as-H1 mode enabled — title counted as H1 equivalent. (Heading tags could not be detected from the rendered page; verify your theme outputs the title correctly.)'=>'حالت H2 به عنوان H1 فعال شد — عنوان به عنوان معادل H1 شمرده می‌شود. (برچسب‌های سرصفحه از صفحه رندر شده قابل تشخیص نبود؛ مطمئن شوید قالب شما عنوان را به درستی خروجی می‌دهد.)','Headings'=>'عناوین','Hide'=>'پنهان کردن','Hints'=>'راهنماها','Home link text'=>'متن لینک صفحه اصلی','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'چگونه باید در ترجمه ظاهر شود. همان مقدار منبع را تایپ کنید تا هوش مصنوعی آن را به صورت کلمه به کلمه حفظ کند.','How to use'=>'نحوه استفاده','Hreflang'=>'Hreflang','Hreflang output'=>'خروجی hreflang','Hreflang settings saved.'=>'تنظیمات hreflang ذخیره شد.','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'آیکون + برچسب','Icon only'=>'فقط آیکون','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'اگر علامت زده شود، حذف افزونه تمام تخصیص‌های زبان، روابط ترجمه، توضیحات متا، پیش‌تنظیمات صفحه، واژه‌نامه هوش مصنوعی و حافظه ترجمه هر پست در این سایت را به طور دائم حذف می‌کند. این عملیات قابل بازگشت نیست. مگر اینکه کاملاً پشتیبانی چندزبانه سایت را حذف کنید، این گزینه را غیرفعال نگه دارید.','If you have a general SEO plugin installed, this panel shows how LF adapts to avoid duplicate output. The goal is collision avoidance — not cooperation. LF always provides the multilingual SEO layer (hreflang, og:locale, inLanguage schema) that requires knowledge of LF\'s language routing configuration to produce correctly.'=>'اگر پلاگین SEO عمومی نصب کرده‌اید، این پنل نشان می‌دهد که LF چگونه سازگار می‌شود تا خروجی تکراری را جلوگیری کند. هدف جلوگیری از تداخل است — نه همکاری. LF همیشه لایه SEO چندزبانه (hreflang، og:locale، درون‌ساخت schema) را فراهم می‌کند که نیازمند دانش درباره پیکربندی مسیریابی زبان LF است تا به درستی تولید شود.','If you have Yoast SEO, Rank Math, All in One SEO, or SEOPress installed, Lingua Forge detects them and adapts to avoid duplicate output. For hreflang, LF takes over entirely and suppresses the plugin\'s output because those plugins cannot produce correct hreflang for a multilingual routing configuration. For Open Graph, LF adds only og:locale and og:locale:alternate — the multilingual signals the plugin cannot provide — and leaves the base OG set to the plugin. For Schema.org, LF disables its own output entirely to avoid conflicting JSON-LD graphs.'=>'اگر Yoast SEO، Rank Math، All in One SEO یا SEOPress نصب کرده‌اید، Lingua Forge آن‌ها را شناسایی می‌کند و سازگار می‌شود تا خروجی تکراری را جلوگیری کند. برای hreflang، LF کاملاً کنترل را در دست می‌گیرد و خروجی پلاگین را سرکوب می‌کند چون این پلاگین‌ها نمی‌توانند hreflang صحیح برای پیکربندی مسیریابی چندزبانه تولید کنند. برای Open Graph، LF فقط og:locale و og:locale:alternate را اضافه می‌کند — سیگنال‌های چندزبانه که پلاگین نمی‌تواند ارائه دهد — و مجموعه OG پایه را به پلاگین می‌سپارد. برای Schema.org، LF خروجی خود را کاملاً غیرفعال می‌کند تا از تداخل گراف‌های JSON-LD جلوگیری کند.','Images'=>'تصاویر','Improve writing'=>'بهبود نوشتار','In the block editor, add a Social Icons block. For each icon, open the link settings and enter one of the "share:" values below as the URL. On the frontend, LF replaces it with the correct share URL for the current page.'=>'در ویرایشگر بلوک، یک بلوک آیکون‌های اجتماعی اضافه کنید. برای هر آیکون، تنظیمات لینک را باز کنید و یکی از مقادیر "share:" زیر را به عنوان URL وارد کنید. در فرانت‌اند، LF آن را با URL اشتراک صحیح برای صفحه جاری جایگزین می‌کند.','Includes name, description, inLanguage, url, image, and an Offer with price, priceCurrency, and availability. Price and availability come from the source-language product (shared stock model).'=>'شامل نام، توضیحات، inLanguage، url، تصویر و یک پیشنهاد با قیمت، ارز قیمت و در دسترس بودن. قیمت و در دسترس بودن از محصول زبان منبع (مدل سهام مشترک) گرفته شده است.','Includes site name, url, and inLanguage.'=>'شامل نام سایت، url و inLanguage.','Informative'=>'اطلاعاتی','Input tokens'=>'توکن‌های ورودی','Install'=>'نصب','Install a Language'=>'نصب یک زبان','Installed SEO plugins'=>'پلاگین‌های SEO نصب شده','Installing…'=>'در حال نصب…','instock / oos / pending from WC stock status'=>'در انبار / خارج از موجودی / در انتظار از وضعیت موجودی WC','Instructions (optional)'=>'دستورالعمل‌ها (اختیاری)','Instructions / key points'=>'دستورالعمل‌ها / نکات کلیدی','Integration API'=>'رابط برنامه‌نویسی یکپارچه‌سازی','Internal Link Fixer'=>'برطرف‌کننده لینک داخلی','Introduction only'=>'فقط مقدمه','Invalid file reference.'=>'مرجع فایل نامعتبر است.','Invalid filename.'=>'نام فایل نامعتبر است.','Invalid language code.'=>'کد زبان نامعتبر است.','Invalid language.'=>'زبان نامعتبر.','Invalid locale code.'=>'کد محلی نامعتبر است.','Invalid or primary language.'=>'زبان نامعتبر یا اصلی.','Invalid post ID.'=>'شناسه پست نامعتبر است.','Invalid post type.'=>'نوع پست نامعتبر.','Invalid template part.'=>'قسمت قالب نامعتبر است.','Invalid template type.'=>'نوع الگو نامعتبر است.','JavaScript-powered actions'=>'اقدامات مبتنی بر JavaScript','Key points, ideas, or structure to build from…'=>'نکات کلیدی، ایده‌ها یا ساختاری که باید از آن شروع کنید…','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'کلیدهای API قبل از ذخیره در پایگاه داده وردپرس با AES-256-CBC رمزگذاری می‌شوند. کلید رمزگذاری از نمک‌های احراز هویت وردپرس شما (wp-config.php) استخراج می‌شود، بنابراین کلیدهای متن‌پایه هرگز به پایگاه داده وارد نمی‌شوند.','Landing / Short-form'=>'صفحه فرود / فرم کوتاه','Language'=>'زبان','Language %s installed successfully.'=>'زبان %s با موفقیت نصب شد.','Language (optional)'=>'زبان (اختیاری)','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'نصب زبان در این سرور غیرفعال است (DISALLOW_FILE_MODS تنظیم شده است).','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'نصب زبان در این سرور غیرفعال است. ثابت DISALLOW_FILE_MODS در wp-config.php تنظیم شده است. بسته‌های زبان را به صورت دستی از طریق WP-CLI نصب کنید: wp language core install de_DE','Language label'=>'برچسب زبان','Language Overrides'=>'نحوه جایگزینی زبان','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'پیش‌فرض‌های زبان: مدیریت فایل‌های جایگزین .po/.mo سفارشی برای رشته‌های رابط کاربری Lingua Forge. از این به جای ویرایش مستقیم فایل‌های پلاگین استفاده کنید — جایگزین‌ها پس از بروزرسانی باقی می‌مانند.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'نصب بسته زبان شکست خورد. ممکن است زبان قبلاً نصب شده باشد، کد محلی نادرست باشد، یا سرور شما نوشتن فایل‌ها را مسدود کند.','Language Setup'=>'راه‌اندازی زبان','Language Switcher'=>'سوئیچ زبان','Language switcher'=>'سوئیچر زبان','Language uninstalled. %d post deleted.'=>'زبان حذف شده است. %d پست حذف شد.' . "\0" . 'زبان حذف شده است. %d پست حذف شد.','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'نسخه‌های خاص زبان از قسمت‌های قالب قالب. پس از اسکافولد، قالب‌ها به‌روزرسانی می‌شوند تا به قسمت‌های خاص زبان ارجاع دهند.','Language:'=>'زبان:','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'زبان‌هایی که در حال حاضر به مسیر یاب شناخته شده‌اند (برگرفته از بسته‌های محلی وردپرس نصب شده به علاوه زبان اصلی). بسته‌های زبان اضافی را در بخش زیر نصب کنید تا زبان‌های بیشتری برای مسیر یابی و ترجمه در دسترس باشد.','Last 30 days'=>'سی روز گذشته','Last 7 days'=>'هفت روز گذشته','Last generated: %s'=>'آخرین تولید: %s','Lead paragraph (≤60 w)'=>'پیش‌نویس اولیه (≤60 کلمه)','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'برای استفاده از مدل پیش‌فرض داخلی، فیلد مدل را خالی بگذارید. متن جای‌گذاری نشان می‌دهد کدام مدل استفاده خواهد شد.','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'برای نام‌های تجاری و اصطلاحات بدون زبان که باید بدون توجه به زبان ترجمه حفظ شوند، خالی بگذارید.','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'برای اعمال این ورودی در تمام زبان‌های هدف — مناسب برای نام‌های تجاری، اختصارات، و اصطلاحاتی که باید به صورت کلمه به کلمه در هر ترجمه حفظ شوند.','Leave blank to keep the existing key. Enter a new value to replace it.'=>'خالی بگذارید تا کلید موجود حفظ شود. مقدار جدید وارد کنید تا جایگزین آن شود.','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'خالی بگذارید تا از پیش‌فرض داخلی استفاده شود. پاک کردن یک تغییر ذخیره شده، پیش‌فرض را در ذخیره‌سازی بعدی بازیابی می‌کند.','Legacy lf-social-share mu-plugin'=>'پلاگین قدیمی lf-social-share','Legacy lf-social-share mu-plugin detected. LF is deferring the base OG set to the mu-plugin and outputting og:locale + og:locale:alternate only. You can deactivate the mu-plugin — LF\'s built-in Social Share (SEO → Social Share tab) and Open Graph cover the same functionality.'=>'پلاگین قدیمی lf-social-share شناسایی شد. LF مجموعه OG پایه را به پلاگین واگذار می‌کند و فقط og:locale + og:locale:alternate را خروجی می‌دهد. می‌توانید پلاگین را غیرفعال کنید — LF\'s built-in Social Share (تب SEO → Social Share) و Open Graph همان عملکرد را دارند.','Legal / Compliance'=>'حقوقی / تطابق','Legal / Compliance instructions'=>'دستورالعمل‌های حقوقی / تطابق','LF always adds og:locale and og:locale:alternate — the multilingual OG signals no general SEO plugin can produce correctly. For the base OG set (og:title, og:description, og:image), LF outputs it when no other plugin is present. When a SEO plugin is installed, LF skips the base set to avoid duplicate tags — not because the plugin is "better", but because duplication produces no value.'=>'LF همیشه og:locale و og:locale:alternate را اضافه می‌کند — سیگنال‌های چندزبانه که هیچ پلاگین SEO عمومی نمی‌تواند به درستی تولید کند. برای مجموعه OG پایه (og:title، og:description، og:image)، LF آن را زمانی که پلاگین دیگری نصب نشده است، خروجی می‌دهد. زمانی که پلاگین SEO نصب است، LF مجموعه پایه را برای جلوگیری از تگ‌های تکراری رد می‌کند — نه به خاطر اینکه پلاگین "بهتر" است، بلکه چون تکرار بی‌فایده است.','LF generates its own sitemap with xhtml:link alternates for all translation groups. When a SEO plugin is installed, it generates a separate sitemap — both coexist independently. Submit both to Google Search Console: the SEO plugin sitemap for content discovery, the LF sitemap for language relationship signals.'=>'LF سایت‌مپ خود را با لینک‌های XHTML:link برای تمام گروه‌های ترجمه تولید می‌کند. زمانی که پلاگین SEO نصب است، سایت‌مپ جداگانه‌ای تولید می‌کند — هر دو مستقل از هم coexist می‌کنند. هر دو را به Google Search Console ارسال کنید: سایت‌مپ پلاگین SEO برای کشف محتوا، سایت‌مپ LF برای سیگنال‌های رابطه زبانی.','LF is outputting hreflang tags and has removed the WordPress core canonical tag on multilingual pages.'=>'LF در حال خروجی تگ‌های hreflang است و تگ canonical هسته وردپرس را در صفحات چندزبانه حذف کرده است.','LF is suppressing hreflang output from: %s'=>'LF در حال سرکوب خروجی hreflang از: %s','LF outputs accurate hreflang for every configured language, including x-default. General SEO plugins have no access to your LF routing configuration and would produce hreflang based on incorrect URL assumptions. LF suppresses their output via filter to prevent collisions.'=>'LF خروجی‌های hreflang دقیقی برای هر زبان پیکربندی‌شده، از جمله x-default، ارائه می‌دهد. افزونه‌های عمومی SEO به پیکربندی مسیریابی LF دسترسی ندارند و بر اساس فرضیات نادرست URL hreflang تولید می‌کنند. LF خروجی آن‌ها را از طریق فیلتر برای جلوگیری از تداخل‌ها سرکوب می‌کند.','LF outputs multilingual JSON-LD with inLanguage annotations tied to its language routing configuration. When a SEO plugin is installed, LF disables its own schema entirely: duplicate JSON-LD graphs produce validation errors and there is no clean way to supplement an existing graph.'=>'LF JSON-LD چندزبانه با برچسب‌های inLanguage مرتبط با پیکربندی مسیریابی زبانی خود را خروجی می‌دهد. زمانی که یک افزونه SEO نصب شده است، LF کاملاً طرح‌واره خود را غیرفعال می‌کند: نمودارهای JSON-LD تکراری خطاهای اعتبارسنجی ایجاد می‌کنند و راهی پاک برای افزودن به نمودار موجود وجود ندارد.','LF provides'=>'LF ارائه می‌دهد','LF removes the WordPress core canonical tag on multilingual pages because the router\'s language-prefixed rewrite rules and the hreflang x-default are the correct canonical signals for a multilingual site. This prevents a double-canonical if a SEO plugin also outputs one. LF does not add its own canonical — the language routing already makes each URL canonical.'=>'LF تگ canonical هسته وردپرس را در صفحات چندزبانه حذف می‌کند زیرا قوانین بازنویسی با پیش‌فرض زبان و hreflang x-default سیگنال‌های canonical صحیح برای یک سایت چندزبانه هستند. این از تکراری بودن canonical جلوگیری می‌کند اگر یک افزونه SEO نیز یکی تولید کند. LF خودش canonical نمی‌افزاید — مسیریابی زبانی در حال حاضر هر URL را canonical می‌کند.','Light'=>'سبک','Light (default — fast and cost-effective)'=>'سبک سبک (پیش‌فرض — سریع و اقتصادی)','Light (fast and cost-effective — Haiku / Flash)'=>'سبک سبک (سریع و اقتصادی — Haiku / Flash)','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'روشن: برای توضیحات متا و تولید بخش کوتاه — سریع، کم هزینه.','Limit results to pages in the given Lingua Forge language code.'=>'نتایج را محدود به صفحات در کد زبان لینگوآ فورج مورد نظر کنید.','Limits'=>'محدودیت‌ها','Lingua Forge'=>'لانگوا فورج','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forge مسیریابی چندزبانه، ترجمه مبتنی بر هوش مصنوعی، برچسب‌های SEO hreflang، و سوئیچر زبان را به سایت وردپرس شما اضافه می‌کند.','Lingua Forge adds WooCommerce-specific Open Graph properties to product pages so that sharing a product URL on Facebook, Pinterest, and similar platforms surfaces the correct product type, price, and availability.'=>'Lingua Forge ویژگی‌های Open Graph مخصوص ووکامرس را به صفحات محصول اضافه می‌کند تا هنگام اشتراک‌گذاری URL محصول در فیسبوک، پینترست و پلتفرم‌های مشابه، نوع محصول، قیمت و موجودی صحیح نمایش داده شود.','Lingua Forge AI Tools'=>'ابزارهای هوش مصنوعی لینگو فورج','Lingua Forge extends the WordPress Core Social Icons block with dynamic share URLs. Set any icon\'s link to a "share:" value and LF rewrites it to the correct share URL or JavaScript action at render time — no custom code or third-party plugin required.'=>'Lingua Forge بلوک آیکون‌های اجتماعی هسته وردپرس را با URLهای اشتراک دینامیک گسترش می‌دهد. هر لینک آیکون را به مقدار "share:" تنظیم کنید و LF آن را در زمان رندر به URL اشتراک صحیح یا اقدام JavaScript بازنویسی می‌کند — نیازی به کد سفارشی یا افزونه شخص ثالث نیست.','Lingua Forge generates a dedicated XML sitemap at /lf-sitemap.xml that adds language alternate links for all your translated content. This sitemap complements the WordPress core sitemap and any SEO plugin sitemap — it does not replace them.'=>'Lingua Forge یک نقشه سایت XML اختصاصی در /lf-sitemap.xml تولید می‌کند که لینک‌های جایگزین زبان برای تمام محتوای ترجمه‌شده شما را اضافه می‌کند. این نقشه سایت مکمل نقشه سایت هسته وردپرس و هر نقشه سایت افزونه SEO است — جایگزین آن‌ها نیست.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin is required.'=>'Lingua Forge یک راه‌حل کامل SEO چندزبانه است. نیازی به افزونه SEO اضافی نیست.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin or sitemap plugin is required.'=>'Lingua Forge یک راه‌حل کامل SEO چندزبانه است. نیازی به افزونه SEO یا نقشه سایت اضافی نیست.','Lingua Forge outputs <link rel="alternate" hreflang> tags for every configured language on every page, including x-default pointing to the source language. This is the primary multilingual SEO signal for Google and other search engines — no additional SEO plugin is required.'=>'Lingua Forge برچسب‌های <link rel="alternate" hreflang> را برای هر زبان پیکربندی‌شده در هر صفحه، از جمله x-default که به زبان منبع اشاره دارد، تولید می‌کند. این سیگنال اصلی سئو چندزبانه برای گوگل و سایر موتورهای جستجو است — نیازی به افزونه سئو اضافی نیست.','Lingua Forge outputs Open Graph and Twitter Card meta tags so shared URLs display the correct language, title, description, and image on social platforms.'=>'Lingua Forge برچسب‌های متا Open Graph و Twitter Card را خروجی می‌دهد تا URLهای اشتراک‌گذاری شده زبان، عنوان، توضیحات و تصویر صحیح را در پلتفرم‌های اجتماعی نمایش دهند.','Lingua Forge outputs Schema.org JSON-LD structured data so search engines understand your content type, language, and metadata. This is the primary way to communicate inLanguage annotations for multilingual content to Google and other crawlers.'=>'Lingua Forge داده‌های ساختاری JSON-LD Schema.org را خروجی می‌دهد تا موتورهای جستجو نوع محتوا، زبان و متادیتای شما را درک کنند. این روش اصلی برای ارتباط برچسب‌های inLanguage برای محتوای چندزبانه با گوگل و دیگر خزنده‌ها است.','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge به طور پیش‌فرض دو ویژگی Gutenberg را محدود می‌کند تا رفتار ویرایشی در سراسر زبان‌ها سازگار باقی بماند. در اینجا انتخاب کنید زمانی که به قابلیت‌های کامل Gutenberg / FSE نیاز دارید.','Lingua Forge Settings'=>'تنظیمات Lingua Forge','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forge از دو لایه کش مستقل برای جلوگیری از درخواست‌های تکراری API هوش مصنوعی استفاده می‌کند. از زبانه‌های زیر برای بررسی و مدیریت هر یک استفاده کنید.','Lingua Forge uses two model tiers per provider:'=>'Lingua Forge از دو سطح مدل برای هر ارائه‌دهنده استفاده می‌کند:','Lingua Forge — Quick Translate'=>'لانگوا فورج — ترجمه سریع','Lingua Forge — Settings'=>'لینگوا فورج — تنظیمات','Lingua Forge\'s built-in Social Share and Open Graph modules cover all functionality the mu-plugin provides, plus multilingual og:locale support. You can safely deactivate the mu-plugin.'=>'ماژول‌های داخلی اشتراک اجتماعی و Open Graph Lingua Forge تمام عملکردهای ارائه شده توسط mu-plugin را پوشش می‌دهند، به‌علاوه پشتیبانی چندزبانه og:locale. می‌توانید به‌طور ایمن mu-plugin را غیرفعال کنید.','Link copied'=>'لینک کپی شد','link(s)'=>'لینک‌ها','Links'=>'لینک‌ها','Load available languages'=>'بارگذاری زبان‌های در دسترس','Load content'=>'بارگذاری محتوا','Loaded from cache.'=>'بارگذاری شده از کش.','Loading…'=>'در حال بارگذاری…','Locale only'=>'فقط منطقه','Locked — a conflicting SEO plugin is active. See the notice above.'=>'قفل شده — یک افزونه SEO تداخل‌گر فعال است. بالا را ببینید.','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate ترجمه‌های سفارشی خود را در wp-content/languages/loco/ ذخیره می‌کند — محلی که ممکن است به طور مخفی توسط بروزرسانی هسته WP، نصب مجدد پلاگین، یا حذف خود Loco Translate پاک شود. کپی کردن فایل‌ها در اینجا آنها را به دایرکتوری Lingua Forge i18n-overrides منتقل می‌کند، که در تمام این رویدادها باقی می‌ماند و به طور خودکار در هر درخواست بارگذاری می‌شود.','Loco Translate — Copy to Safe Storage'=>'Loco Translate — کپی به ذخیره‌سازی امن','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'کم‌ترین قابلیت وردپرس مجاز برای فعال کردن ویژگی‌های هوش مصنوعی. محدود کردن این نقش در سایت‌های چندنویسنده از اجرای تماس‌های پولی هوش مصنوعی توسط مشارکت‌کنندگان یا حساب‌های آزمایشی جلوگیری می‌کند. این محدودیت را از طریق فیلتر linguaforge_required_capability برای هر ویژگی به صورت جداگانه تغییر دهید.','Maintenance'=>'نگهداری','Maintenance Tab'=>'تب نگهداری','Make casual'=>'مُدرن کردن','Make concise'=>'مختصر کردن','Make formal'=>'رسمی کردن','Mark citations needed'=>'علامت‌گذاری نیاز به استناد','Max context characters'=>'حداکثر کاراکترهای زمینه','Max hints characters'=>'حداکثر کاراکترهای راهنمایی','Max input characters'=>'حداکثر کاراکترهای ورودی','Max output tokens'=>'حداکثر توکن‌های خروجی','Maximum characters accepted from the input field. Default: 8 000.'=>'حداکثر کاراکترهای مجاز از فیلد ورودی. پیش‌فرض: 8000.','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'حداکثر کاراکترهای محتوای پست موجود که به عنوان زمینه بذر به هوش مصنوعی منتقل می‌شود زمانی که راهنمایی ارائه نشده است. پیش‌فرض: 6000.','Maximum characters read from the Hints field. Default: 2 000.'=>'حداکثر کاراکترهای خوانده شده از فیلد راهنمایی. پیش‌فرض: 2000.','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'حداکثر تعداد کاراکترهای محتوای پستی که به هوش مصنوعی ارسال می‌شود. 0 یعنی بدون محدودیت — محتوای کامل همیشه ارسال می‌شود (پیشنهادی). مقدار غیرصفر فقط در صورتی تنظیم شود که ارائه‌دهنده شما دارای پنجره‌ی محدودیت محتوای تنگ باشد. هر زمان محتوا کوتاه شود، یک هشدار در گزارش خطای PHP ثبت می‌شود.','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'حداکثر تعداد توکن‌هایی که هوش مصنوعی می‌تواند در یک پاسخ ترجمه تولید کند. اگر ترجمه به طور خاموش در انتها قطع شد، این مقدار را افزایش دهید. پیش‌فرض: 16000.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'حداکثر توکن‌هایی که هوش مصنوعی ممکن است در هر اجرا تولید کند. در صورت قطع شدن کامل مقالات، این مقدار را افزایش دهید. پیش‌فرض: 8192.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'حداکثر توکن‌هایی که هوش مصنوعی ممکن است در هر ترجمه سریع تولید کند. پیش‌فرض: 2000.','Meta Description'=>'توضیحات متا','Meta description'=>'توضیحات متا','Meta Description, Excerpt Generator'=>'تولید توضیحات متا، خلاصه','Metric'=>'معیار','Minimum role'=>'حداقل نقش','Missing pattern name or language.'=>'نام الگو یا زبان گمشده است.','Mode'=>'حالت','Model'=>'مدل','Model tier'=>'سطح مدل','Models'=>'مدل‌ها','Models Tab (General)'=>'تب مدل‌ها (عمومی)','Modified'=>'تغییر یافته','Most recent cached block'=>'جدیدترین بلوک کش شده','Most recent cached response'=>'جدیدترین پاسخ کش شده','Multilingual routing, complete multilingual SEO (hreflang, Open Graph, Schema.org, sitemap), and AI content tools for WordPress. Language detection, URL routing, translation, content generation, and a full SEO layer — no companion plugin required.'=>'مسیر چندزبانه، سئو کامل چندزبانه (hreflang، Open Graph، Schema.org، نقشه سایت)، و ابزارهای محتوای هوش مصنوعی برای وردپرس. تشخیص زبان، مسیر URL، ترجمه، تولید محتوا، و یک لایه کامل سئو — بدون نیاز به افزونه همراه.','Name displayed in this language. Leave empty to use the source name.'=>'نام نمایش داده شده در این زبان. برای استفاده از نام منبع خالی بگذارید.','Navigation'=>'ناوبری','Navigation has no content to translate.'=>'ناوبری محتوا برای ترجمه ندارد.','Navigation not found.'=>'ناوبری یافت نشد.','Navigation posts are translated via the Router tab, not this button.'=>'پست‌های ناوبری از طریق برگه مسیریاب ترجمه می‌شوند، نه این دکمه.','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'ترجمه ناوبری نیازمند یک ارائه‌دهنده هوش مصنوعی فعال است. یک کلید API را در برگه کلیدهای API پیکربندی کنید.','Navigations'=>'ناوبری‌ها','Network error — could not reach the WordPress AJAX endpoint.'=>'خطای شبکه — نتوانست به نقطه انتهای AJAX وردپرس دسترسی پیدا کند.','No %s version found in this translation group.'=>'در این گروه ترجمه نسخه %s یافت نشد.','No action needed. Google deprecated its sitemap ping endpoint in January 2024 and now discovers sitemaps exclusively via the robots.txt Sitemap: directive — which LF has already configured. Google will pick it up on its next crawl.'=>'نیازی به اقدام نیست. گوگل در ژانویه ۲۰۲۴ نقطه پایانی پینگ نقشه سایت خود را منسوخ کرد و اکنون نقشه‌های سایت را تنها از طریق دستور robots.txt Sitemap: کشف می‌کند — که LF قبلاً پیکربندی کرده است. گوگل در بازدید بعدی آن را دریافت خواهد کرد.','No AI provider configured.'=>'پروایدر هوش مصنوعی پیکربندی نشده است.','No AI provider configured. Add an API key in Settings → API Keys.'=>'هیچ ارائه‌دهنده AI پیکربندی نشده است. یک کلید API در تنظیمات → کلیدهای API اضافه کنید.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'در بازه زمانی انتخاب شده (%s) استفاده‌ای از هوش مصنوعی ثبت نشده است. بازه وسیع‌تری را انتخاب کنید.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'تا کنون استفاده‌ای از هوش مصنوعی ثبت نشده است. پس از اجرای ترجمه، تولید توضیحات متا، یا استفاده از هر ویژگی دیگر هوش مصنوعی، مجموع‌ها در اینجا ظاهر می‌شوند.','No API key configured for this provider.'=>'برای این ارائه‌دهنده کلید API پیکربندی نشده است.','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'هیچ دستورالعمل داخلی وجود ندارد — هر ویژگی هوش مصنوعی از تنظیمات پیش‌فرض خود استفاده می‌کند. برای افزودن قوانین سایت خود، فیلد دستورالعمل‌های سفارشی را در زیر پر کنید.','No conflicting SEO plugins detected. Lingua Forge is handling all SEO output independently.'=>'هیچ افزونه SEO تداخل‌گر شناسایی نشده است. Lingua Forge تمام خروجی‌های SEO را به‌طور مستقل مدیریت می‌کند.','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'هنوز فایل‌های سفارشی Loco Translate یافت نشدند. آنها پس از ذخیره ترجمه در Loco Translate در اینجا ظاهر می‌شوند.','No external OG plugin detected. LF is outputting the full OG + Twitter Card set.'=>'هیچ افزونه OG خارجی شناسایی نشده است. LF مجموعه کامل OG + Twitter Card را خروجی می‌دهد.','No file was selected.'=>'هیچ فایلی انتخاب نشده است.','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'هیچ ورودی واژگان مطابق فیلتر فعلی نیست. فیلتر را پاک کنید تا همه ورودی‌ها را ببینید، یا ورودی جدیدی در زیر اضافه کنید.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'هنوز ورودی واژگان وجود ندارد. یکی در زیر اضافه کنید تا اجرای اصطلاحات در ترجمه‌ها شروع شود.','No H1 found. Typically the post title is the H1 — verify your theme is outputting it.'=>'هیچ H1 یافت نشد. معمولاً عنوان پست H1 است — اطمینان حاصل کنید که قالب شما آن را خروجی می‌دهد.','No images found in content.'=>'هیچ تصویری در محتوا یافت نشد.','No internal links found to update.'=>'هیچ لینک داخلی برای به‌روزرسانی یافت نشد.','No language-specific template parts found to map.'=>'قسمت‌های قالب خاص زبانی برای نقشه‌برداری پیدا نشد.','No LF meta description set — using excerpt/content.'=>'توضیحات متا LF تنظیم نشده است — از بخش گزیده/محتوا استفاده می‌شود.','No links found.'=>'هیچ لینکی یافت نشد.','No links found. Internal links improve crawlability and user navigation.'=>'هیچ لینکی یافت نشد. لینک‌های داخلی قابلیت خزیدن و ناوبری کاربر را بهبود می‌بخشند.','No meta description found. Generate one via the AI meta description feature.'=>'هیچ توضیحات متای یافت نشد. آن را از طریق ویژگی توضیحات متای AI تولید کنید.','No navigation references needed updating.'=>'نیاز به به‌روزرسانی ارجاعات ناوبری نیست.','No override files uploaded yet.'=>'هنوز فایل جایگزینی آپلود نشده است.','No physical robots.txt file found. WordPress is generating it virtually and LF\'s Sitemap directive is included automatically.'=>'هیچ فایل robots.txt فیزیکی یافت نشد. وردپرس آن را به صورت مجازی تولید می‌کند و دستور نقشه سایت LF به‌طور خودکار شامل است.','No published posts found for the selected filters.'=>'هیچ پستی منتشر شده برای فیلترهای انتخاب شده یافت نشد.','No response from AI provider. Check your API key and try again.'=>'هیچ پاسخ از ارائه‌دهنده AI دریافت نشد. کلید API خود را بررسی کنید و دوباره تلاش کنید.','No response from provider — check the error log for details.'=>'پاسخی از ارائه‌دهنده دریافت نشد — برای جزئیات، لاگ خطا را بررسی کنید.','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'هیچ زبان ثانویه‌ای پیکربندی نشده است. برای فعال‌سازی اسکافولد قالب، یک بسته زبان در بالا نصب کنید.','No source content found to translate.'=>'محتوای منبع برای ترجمه یافت نشد.','No source page linked yet.'=>'هنوز صفحه منبع لینک نشده است.','No template part references needed updating.'=>'نیاز به به‌روزرسانی ارجاعات قسمت قالب نیست.','No title set.'=>'عنوان تنظیم نشده است.','No translated content found. The sitemap will populate once posts have been translated.'=>'محتوای ترجمه‌شده یافت نشد. نقشه سایت پس از ترجمه پست‌ها پر می‌شود.','No translation found — analyzed the source language version.'=>'ترجمه‌ای یافت نشد — نسخه زبان منبع تحلیل شد.','No {lang} translation registered (TRID missing)'=>'ترجمه {lang} ثبت نشده است (TRID مفقود است)','Not yet generated. The sitemap is built on the first visit to the sitemap URL and cached for 24 hours.'=>'هنوز ساخته نشده است. نقشه سایت در اولین بازدید از URL نقشه سایت ساخته می‌شود و برای ۲۴ ساعت کش می‌شود.','Notes'=>'یادداشت‌ها','Nothing — all types disabled'=>'هیچ — همه نوع‌ها غیرفعال شده‌اند','Notice message'=>'پیام اطلاع‌رسانی','Notice settings'=>'تنظیمات اطلاع‌رسانی','Notify search engines'=>'اعلان به موتورهای جستجو','OG/Twitter Card tags: handled by LF\'s Open Graph module (SEO → Open Graph & Twitter Cards)'=>'برچسب‌های OG/Twitter Card: توسط ماژول Open Graph LF (SEO → Open Graph & Twitter Cards) مدیریت می‌شود','Oldest cached block'=>'قدیمی‌ترین بلوک کش شده','Oldest cached response'=>'قدیمی‌ترین پاسخ کش شده','Only .mo files are accepted.'=>'فقط فایل‌های .mo پذیرفته می‌شوند.','Open Graph'=>'Open Graph','Open Graph &amp; Twitter Cards'=>'کارت‌های Open Graph و توییتر','Open Graph output'=>'خروجی Open Graph','Open Graph settings saved.'=>'تنظیمات Open Graph ذخیره شد.','Open Search Console →'=>'باز کردن کنسول جستجو →','Open the browser\'s native Web Share sheet (iOS, Android, some desktops). Falls back to clipboard copy if not supported.'=>'باز کردن صفحه اشتراک وب مرورگر (iOS، Android، برخی دسکتاپ‌ها). در صورت عدم پشتیبانی به کلیپ‌بورد کپی می‌کند.','OpenAI (GPT)'=>'اوپن‌ای‌آی (جی‌پی‌تی)','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'زمینه اختیاری برای ویرایشگران (مثلاً "ASIC = مدار مجتمع خاص برنامه؛ در زمینه‌های فنی به انگلیسی حفظ شود").','Optional. Bing already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'اختیاری. بینگ در حال حاضر دستور Sitemap: را از robots.txt می‌خواند — این فقط یک بازپیمایی فوری را فعال می‌کند و منتظر بررسی بعدی نمی‌ماند.','Optional. Yandex already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'اختیاری. یاندکس در حال حاضر دستور Sitemap: را از robots.txt می‌خواند — این فقط یک بازپیمایی فوری را فعال می‌کند و منتظر بررسی بعدی نمی‌ماند.','Output'=>'خروجی','Output Article or WebPage schema on singular posts and pages'=>'نمایش طرح Article یا WebPage در پست‌ها و صفحات تکی','Output hreflang tags in wp_head'=>'نمایش برچسب‌های hreflang در wp_head','Output mode'=>'حالت خروجی','Output Open Graph tags in wp_head'=>'نمایش برچسب‌های Open Graph در wp_head','Output Product schema on WooCommerce product pages'=>'نمایش طرح Product در صفحات محصول ووکامرس','Output Schema.org JSON-LD in wp_head'=>'خروجی Schema.org JSON-LD در wp_head','Output tokens'=>'توکن‌های خروجی','Output WebSite schema on the front page and blog index'=>'خروجی اسکیمای وب‌سایت در صفحه اصلی و فهرست وبلاگ','Overall SEO score'=>'امتیاز کلی سئو','overridden'=>'بازنویسی شده','Override file deleted.'=>'فایل جایگزین حذف شد.','Override file uploaded successfully.'=>'فایل جایگزین با موفقیت آپلود شد.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'پیش‌فرض هوش مصنوعی برای ترجمه و تولید محتوا در این صفحه را جایگزین می‌کند. سایر ویژگی‌ها همیشه از پیش‌فرض جهانی استفاده می‌کنند.','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'پیش‌فرض هوش مصنوعی برای ترجمه و تولید محتوا در این صفحه را جایگزین می‌کند. دستورالعمل‌های سفارشی در سطح سایت (تنظیمات → رفتار) همیشه به هر درخواست افزوده می‌شود، صرف‌نظر از این انتخاب.','Overview'=>'مرور کلی','Page'=>'صفحه','Part'=>'قسمت','Paste a footnote, sentence, or any snippet here…'=>'یک پاورقی، جمله، یا هر قطعه‌ای را اینجا قرار دهید…','Paste text, or select text in the editor first…'=>'متن را جای‌گذاری کنید، یا ابتدا متن را در ویرایشگر انتخاب کنید…','Paste text, or select text on the page first…'=>'متن را جای‌گذاری کنید، یا ابتدا متن را در صفحه انتخاب کنید…','Paste your API key…'=>'کلید API خود را جای‌گذاری کنید…','Path prefix — example.com/de/'=>'پیشوند مسیر — example.com/de/','Pattern'=>'الگو','Pattern has no content to translate.'=>'الگو محتوا برای ترجمه ندارد.','Pattern not found.'=>'الگو پیدا نشد.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'الگو ترجمه و ذخیره شد. محتوا را از طریق واردکننده الگو در ویرایشگر بلوک یا به عنوان نقطه شروع برای بلوک قابل استفاده مجدد کپی کنید.','Pattern translation failed.'=>'ترجمه الگو شکست خورد.','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Always active — no separate toggle required. Entries are invalidated automatically when the content or AI provider/model changes.'=>'کش هر پست برای ترجمه‌های تولید شده توسط هوش مصنوعی، توضیحات متا، گزیده‌ها و محتوا. همیشه فعال است — نیاز به سوئیچ جداگانه ندارد. ورودی‌ها به طور خودکار منقضی می‌شوند زمانی که محتوا یا ارائه‌دهنده/مدل هوش مصنوعی تغییر کند.','Permalink rules flushed successfully.'=>'قوانین پیوند یکتا با موفقیت پاک شد.','Permanently deletes all templates, template parts, patterns, navigation menus, posts, pages, custom post types, products, and product variations associated with this language. Also removes the WordPress locale pack files so this language no longer appears in the router. This action cannot be undone.'=>'حذف دائمی تمام قالب‌ها، قسمت‌های قالب، الگوها، منوهای ناوبری، پست‌ها، صفحات، نوع‌های پست سفارشی، محصولات و تنوع‌های محصولات مرتبط با این زبان. همچنین فایل‌های بسته زبان وردپرس را حذف می‌کند تا این زبان دیگر در مسیریاب ظاهر نشود. این عمل قابل بازگشت نیست.','Permanently uninstall %s? This will delete all translated content for this language and cannot be undone.'=>'حذف دائمی %s؟ این کار تمام محتوای ترجمه شده برای این زبان را حذف می‌کند و قابل بازگشت نیست.','Permission denied.'=>'دسترسی ممنوع است.','Persuasive'=>'قانع‌کننده','PHP constant'=>'ثابت PHP','Pin on Pinterest'=>'پین در Pinterest','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'اصطلاحاتی که نباید ترجمه شوند یا باید همیشه به روشی خاص نمایش داده شوند (مثلاً نام‌های تجاری، نام محصولات، مخفف‌ها). محدودیت‌های واژه‌نامه در هر درخواست ترجمه هوش مصنوعی برای تمام ویژگی‌ها وارد می‌شود: ترجمه پست، توضیحات متا، بخش کوتاه، و ترجمه قالب FSE.','Ping Bing'=>'پینگ بینگ','Ping Yandex'=>'پینگ یاندکس','Plain language'=>'زبان ساده','Please enter some instructions first…'=>'لطفاً ابتدا دستورالعمل‌هایی وارد کنید…','Please enter some text first…'=>'لطفاً ابتدا مقداری متن وارد کنید…','Plugin'=>'افزونه','Post'=>'پست','Post not found or not published.'=>'پست پیدا نشد یا منتشر نشده است.','Post not found.'=>'پست پیدا نشد.','Post on X / Twitter'=>'پست در X / توییتر','Post Types'=>'نوع‌های پست','Prefilled from excerpt. Edit to override.'=>'از بخش چکیده پیش‌فرض گرفته شده است. برای جایگزینی ویرایش کنید.','Price and availability always reflect the source-language product (shared stock model). Tags are only output when LF\'s Open Graph module is set to "Full" or "Auto" mode with no conflicting SEO plugin detected.'=>'قیمت و موجودی همیشه محصول منبع زبان را نشان می‌دهد (مدل سهام مشترک). برچسب‌ها تنها زمانی خروجی می‌شوند که ماژول Open Graph LF در حالت "کامل" یا "خودکار" باشد و افزونه سئو تداخلی نداشته باشد.','Primary Language'=>'زبان اصلی','Primary language'=>'زبان اصلی','Primary language saved.'=>'زبان اصلی ذخیره شد.','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'زبان اصلی: زبانی که محتوای فعلی شما به آن نوشته شده است. تمام ترجمه‌ها از این زبان تولید می‌شوند؛ تغییر آن هیچ پستی را جابه‌جا یا حذف نمی‌کند.','Processing…'=>'در حال پردازش…','Product'=>'محصول','Product / eCommerce'=>'محصول / تجارت الکترونیک','Product Open Graph'=>'Open Graph محصول','Product — WooCommerce product pages'=>'محصول — صفحات محصول ووکامرس','Profile'=>'پروفایل','Provider'=>'ارائه‌دهنده','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'ارائه‌دهنده هیچ متنی برنگرداند. برای جزئیات دلیل شکست، گزارش خطای وردپرس را بررسی کنید.','Quality'=>'کیفیت','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'کیفیت (پیش‌فرض — Sonnet / GPT-4o / Gemini Pro)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'کیفیت (سونت / GPT-4o / جمنای پرو)','Quality: used for post translation and content generation — higher quality, higher cost.'=>'کیفیت: برای ترجمه پست و تولید محتوا استفاده می‌شود — کیفیت بالاتر، هزینه بالاتر.','Quick Translate'=>'ترجمه سریع','Quick Translation'=>'ترجمه سریع','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'ترجمه سریع برای حالت برش/قطعه — ترجمه بخش‌های کوتاه بر اساس درخواست از نوار ابزار، ویرایشگر، یا پاپ‌آورهای بلوک. این از پیکربندی جداگانه و سبک‌تر نسبت به ترجمه صفحه کامل استفاده می‌کند تا پاسخ‌ها سریع و اقتصادی باشد.','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'قابل استفاده مجدد برای قابلیت قفل کردن بلوک‌های Gutenberg. مفید برای قالب‌های ویرایشی که نیاز به جلوگیری از جابجایی یا حذف بلوک‌های خاص دارند.','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'قابل استفاده مجدد برای supportTemplateMode. هسته‌ای برای گردش‌های کاری ویرایش کامل سایت که در آن تغییرات سطح پست در قالب‌ها عمدی است.','Re-generates and updates the cached result.'=>'تولید مجدد و به‌روزرسانی نتیجه در حافظه کش.','Re-scan'=>'بازبینی مجدد','Re-scanning…'=>'در حال اسکن مجدد…','Re-translate'=>'بازترجمه','Reading time'=>'زمان مطالعه','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'بازدیدکنندگان را بر اساس هدر Accept-Language مرورگرشان به زبان ترجیحی‌شان هدایت کنید','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'بازبینی بیشتر — مثلا «کوتاه‌تر کردن» یا «استفاده از لحن رسمی»…','Refine further:'=>'بازبینی بیشتر:','Refinement'=>'اصلاح','Refinement failed — please try again.'=>'اصلاح ناموفق بود — لطفاً دوباره تلاش کنید.','Refining…'=>'در حال اصلاح…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'بازنویسی قوانین وردپرس را مجدد تولید می‌کند تا پیشوندهای URL، برچسب‌های زبان خاص و بازنویسی آرشیو همگام شوند. پس از تغییر زبان اصلی یا افزودن پشتیبانی از زبان جدید، لازم است.','Remove stored key'=>'حذف کلید ذخیره شده','Report an issue on GitHub'=>'گزارش مشکل در GitHub','Request failed — please try again.'=>'درخواست ناموفق بود — لطفاً دوباره تلاش کنید.','Request failed.'=>'درخواست ناموفق بود.','Request failed. Check your connection.'=>'درخواست ناموفق. اتصال خود را بررسی کنید.','Request failed. Please try again.'=>'درخواست ناموفق. لطفاً دوباره تلاش کنید.','Requests'=>'درخواست‌ها','Reset'=>'بازنشانی','Result will appear here…'=>'نتیجه در اینجا ظاهر می‌شود…','Retranslate'=>'بازترجمه','Retranslating…'=>'در حال بازترجمه…','Review carefully — links and slugs not updated.'=>'با دقت بررسی کنید — لینک‌ها و اسلاگ‌ها به‌روزرسانی نشده‌اند.','Review translation before applying'=>'پیش از اعمال، ترجمه را بازبینی کنید','Revise'=>'بازنگری','Revision'=>'بازنگری','Revision Type'=>'نوع بازنگری','robots.txt'=>'robots.txt','robots.txt updated with Sitemap directive.'=>'robots.txt با دستور Sitemap به‌روزرسانی شد.','Router'=>'مسیر یاب','Router Tab'=>'تب مسیریاب','Run AI Analysis'=>'اجرای تحلیل هوش مصنوعی','Save analysis settings'=>'ذخیره تنظیمات تحلیل','Save Debug Setting'=>'ذخیره تنظیمات اشکال‌زدایی','Save Hreflang Settings'=>'ذخیره تنظیمات Hreflang','Save Open Graph Settings'=>'ذخیره تنظیمات Open Graph','Save Router Settings'=>'ذخیره تنظیمات مسیر یاب','Save Schema.org Settings'=>'ذخیره تنظیمات Schema.org','Save Settings'=>'ذخیره تنظیمات','Save Sitemap Settings'=>'ذخیره تنظیمات نقشه سایت','Save Social Share Settings'=>'ذخیره تنظیمات اشتراک‌گذاری اجتماعی','Save the post to persist changes.'=>'پست را ذخیره کنید تا تغییرات حفظ شود.','Save Uninstall Setting'=>'ذخیره تنظیمات حذف','Save WooCommerce SEO Settings'=>'ذخیره تنظیمات سئو ووکامرس','Saved to the meta description field when you apply.'=>'در هنگام اعمال، در فیلد توضیحات متا ذخیره می‌شود.','Scan failed: '=>'اسکن شکست خورد: ','Scan request failed. Please try again.'=>'درخواست اسکن شکست خورد. لطفاً دوباره تلاش کنید.','Scanning posts for broken language links…'=>'در حال اسکن پست‌ها برای لینک‌های زبان شکسته…','Schema output deferred.'=>'خروجی Schema به تعویق افتاده است.','Schema.org'=>'Schema.org','Schema.org JSON-LD'=>'JSON-LD Schema.org','Schema.org output'=>'خروجی Schema.org','Schema.org settings saved.'=>'تنظیمات Schema.org ذخیره شد.','Search'=>'جستجو','Search Console is useful for monitoring indexing and coverage errors, but is not required for discovery.'=>'کنسول جستجو برای نظارت بر خطاهای ایندکس و پوشش مفید است، اما برای کشف نیاز نیست.','Search Results'=>'نتایج جستجو','Security check failed — file path is not permitted.'=>'بررسی امنیتی ناموفق بود — مسیر فایل مجاز نیست.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'یک زبان را برای مدیریت قالب‌های FSE، قسمت‌های قالب و منوهای ناوبری آن انتخاب کنید.','Select language'=>'انتخاب زبان','Send via Telegram'=>'ارسال از طریق تلگرام','Send via WhatsApp'=>'ارسال از طریق واتس‌اپ','SEO'=>'سئو','SEO Analysis'=>'تحلیل سئو','SEO character-count info'=>'اطلاعات تعداد کاراکترهای سئو','SEO plugin(s) detected: %s. LF is outputting og:locale and og:locale:alternate only; the detected plugin handles the full OG set.'=>'افزونه‌های سئو شناسایی شده: %s. LF فقط og:locale و og:locale:alternate را خروجی می‌دهد؛ افزونه شناسایی شده مجموعه کامل OG را مدیریت می‌کند.','SEO plugins and conflict avoidance:'=>'افزونه‌های سئو و جلوگیری از تداخل:','SEO Tab'=>'تب سئو','Server setup (subdomain)'=>'راه‌اندازی سرور (زیر دامنه)','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'رفتار پیش‌فرض هوش مصنوعی برای تمام ویژگی‌ها در سراسر سایت. پست‌های فردی می‌توانند این را برای ترجمه و تولید محتوا از طریق جعبه متای Lingua Forge تغییر دهند.','Settings'=>'تنظیمات','Settings saved.'=>'تنظیمات ذخیره شد.','Share on Facebook'=>'اشتراک‌گذاری در فیسبوک','Share on LinkedIn'=>'اشتراک‌گذاری در لینکدین','Share on Mastodon'=>'اشتراک‌گذاری در ماستودون','Share via email (mailto:)'=>'اشتراک‌گذاری از طریق ایمیل (mailto:)','Show home link'=>'نمایش لینک صفحه اصلی','Shown when no translation exists for the visitor\'s language.'=>'وقتی ترجمه‌ای برای زبان بازدیدکننده وجود ندارد، نشان داده می‌شود.','Single'=>'تک‌صفحه','Single %s'=>'تک %s','Single: %s'=>'تک: %s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'سقف درخواست‌های هوش مصنوعی در سراسر سایت در هر روز UTC (شامل ترجمه‌های نوار ابزار و بازبینی‌های بلوک). شمارنده در نیمه‌شب UTC ریست می‌شود. برای غیرفعال کردن محدودیت، مقدار 0 قرار دهید.','Sitemap'=>'نقشه سایت','Sitemap cache flushed. It will be regenerated on the next visit to the sitemap URL.'=>'کش نقشه سایت پاک شد. در بازدید بعدی از URL نقشه سایت مجدداً ساخته می‌شود.','Sitemap output'=>'خروجی نقشه سایت','Sitemap settings saved.'=>'تنظیمات نقشه سایت ذخیره شد.','Sitemap URL'=>'آدرس URL نقشه سایت','Size'=>'اندازه','Social Icons block share: URLs: handled by LF\'s built-in Social Share (SEO → Social Share)'=>'اشتراک‌گذاری بلوک آیکون‌های اجتماعی: URLها: توسط اشتراک‌گذاری اجتماعی داخلی LF (سئو → اشتراک‌گذاری اجتماعی) مدیریت می‌شود','Social Share'=>'اشتراک‌گذاری اجتماعی','Social Share settings saved.'=>'تنظیمات اشتراک‌گذاری اجتماعی ذخیره شد.','Some link fixes failed.'=>'برخی اصلاحات لینک شکست خورد.','Some nav ref fixes failed.'=>'برخی اصلاحات ارجاعات ناوبری شکست خورد.','Some part fixes failed.'=>'برخی اصلاحات قسمت‌ها شکست خورد.','Some parts could not be created.'=>'برخی قسمت‌ها نتوانستند ایجاد شوند.','Some templates could not be created.'=>'برخی قالب‌ها نتوانستند ایجاد شوند.','Some translations failed.'=>'برخی ترجمه‌ها شکست خوردند.','source'=>'منبع','Source file not found.'=>'فایل منبع یافت نشد.','Source lang'=>'زبان منبع','Source language'=>'زبان مبدا','Source term'=>'اصطلاح منبع','Standard'=>'استاندارد','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'نسخه استاندارد از دمای تنظیم شده هر ویژگی استفاده می‌کند: ترجمه T=0.2 (دقیق)، ترجمه سریع T=0.4، تولید محتوا T=0.6 (خلاقانه). سایر پیش‌فرض‌ها دمای ثابت را در تمام ویژگی‌ها اعمال می‌کنند.','Status'=>'وضعیت','Status / Actions'=>'وضعیت / اقدامات','Storytelling'=>'داستان‌گویی','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'حالت حفظ سخت‌گیرانه برای محتوای حقوقی، مقرراتی، پزشکی یا فنی. زمانی که فعال است، هر ویژگی هوش مصنوعی از دمای نمونه‌برداری پایین استفاده می‌کند و پیوست زیر را به سیستم پرامپت خود اضافه می‌کند — اصطلاحات، شماره مقالات، واحدها، نام‌های تجاری و زبان‌های مقرراتی به صورت عین حفظ می‌شوند و پارافرایز نمی‌شوند.','Structured Outline'=>'طرح ساختاری','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'حالت زیر دامنه نیاز دارد که سرور وب شما تمام زیر دامنه‌های زبان (مثلاً de.example.com) را به این نصب وردپرس اشاره دهد. پس از تغییر حالت‌ها، قوانین پیوند یکتا را تازه‌سازی کنید و هر کشی را پاک کنید. اگر URL خانه شما شامل www است (مثلاً www.example.com)، از فیلتر lf_base_domain برای تنظیم دامنه اصلی بدون www استفاده کنید تا زیر دامنه‌ها به درستی ساخته شوند.','Subdomain — de.example.com/'=>'زیر دامنه — de.example.com/','Submit this URL to Google Search Console alongside your main sitemap.'=>'این URL را همراه با نقشه سایت اصلی خود به کنسول جستجوی گوگل ارسال کنید.','Submit to Reddit'=>'ارسال به ردیت','Suggested meta description'=>'توضیحات متا پیشنهادی','Suggested title'=>'عنوان پیشنهادی','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Only one provider is active at a time. Select the active provider on the General tab.'=>'ارائه‌دهندگان پشتیبانی شده: Anthropic (Claude)، OpenAI (GPT)، Google (Gemini). تنها یک ارائه‌دهنده فعال در هر زمان است. ارائه‌دهنده فعال را در تب عمومی انتخاب کنید.','Suppressed: %s.'=>'ممنوع شده: %s.','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6، برای هر ویژگی','Tag'=>'برچسب','Tags emitted'=>'برچسب‌های منتشر شده','Target lang'=>'زبان هدف','Target Language'=>'زبان هدف','Target language'=>'زبان هدف','Target term'=>'اصطلاح هدف','Target: 140–160 chars for optimal SERP display'=>'هدف: ۱۴۰–۱۶۰ کاراکتر برای نمایش بهینه در نتایج جستجو','Technical'=>'فنی','Technical / Scientific'=>'فنی / علمی','Technical / Scientific instructions'=>'دستورالعمل‌های فنی / علمی','Template "%s" already exists.'=>'الگوی "%s" قبلاً وجود دارد.','Template "{expected}" does not exist — create it in the Site Editor first.'=>'قالب "{expected}" وجود ندارد — ابتدا آن را در ویرایشگر سایت ایجاد کنید.','Template has no content.'=>'الگو محتوا ندارد.','Template mode'=>'حالت قالب','Template not found or not stored in the database.'=>'الگو پیدا نشد یا در پایگاه داده ذخیره نشده است.','Template part "%s" already exists.'=>'قسمت قالب "%s" قبلاً وجود دارد.','Template part has no content.'=>'قسمت قالب محتوا ندارد.','Template part not found or not stored in the database.'=>'قسمت قالب پیدا نشد یا در پایگاه داده ذخیره نشده است.','Template Parts'=>'قسمت‌های قالب','Templates'=>'قالب‌ها','Test connection'=>'آزمایش اتصال','Testing…'=>'در حال آزمایش…','Text domain / locale'=>'دامنه متن / زبان','Text to translate'=>'متن برای ترجمه','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Subsequent requests with identical inputs are served from the cache with no API call. The cache is different from Translation Memory: Translation Memory operates at the block level and is shared across posts; the API Response Cache operates at the feature level and is keyed per post.'=>'کش پاسخ‌های API نتیجه خام هر درخواست هوش مصنوعی — ترجمه، توضیحات متا، بخش کوتاه، و تولید محتوا — است که بر اساس هش ورودی‌ها (محتوا، زوج زبان، ارائه‌دهنده، مدل) کلیدگذاری شده است. درخواست‌های بعدی با ورودی‌های مشابه از کش سرو می‌شوند بدون تماس API. کش با حافظه ترجمه متفاوت است: حافظه ترجمه در سطح بلوک عمل می‌کند و در سراسر پست‌ها مشترک است؛ کش پاسخ API در سطح ویژگی عمل می‌کند و برای هر پست کلیدگذاری می‌شود.','The editor did not accept the content — please try again.'=>'ویرایشگر محتوا را نپذیرفت — لطفاً دوباره تلاش کنید.','The following directive is active in your virtual robots.txt:'=>'دستورالعمل زیر در فایل robots.txt مجازی شما فعال است:','The lf-social-share mu-plugin is active.'=>'ماژول lf-social-share فعال است.','The lf-social-share mu-plugin is active. Lingua Forge\'s built-in Social Share is inactive — the mu-plugin handles share URL rewriting and the JS actions.'=>'ماژول lf-social-share فعال است. اشتراک‌گذاری داخلی Lingua Forge غیرفعال است — این ماژول URLهای اشتراک را بازنویسی می‌کند و اقدامات JS را انجام می‌دهد.','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'سطح سبک از مدل سریع در جدول مدل‌ها پیکربندی شده است (پیش‌فرض: هایکوا / فلاش). در صورت نیاز به دقت ترجمه همانند حالت صفحه کامل برای برش‌ها، به کیفیت تغییر دهید.','The phrase as it appears in the source text.'=>'عبارتی که در متن منبع ظاهر می‌شود.','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'زبان اصلی همیشه در ریشه سایت شما سرویس می‌شود — بدون پیش‌وند URL در حالت مسیر، بدون زیر دامنه زبان در حالت زیر دامنه. سایر زبان‌ها یا از پیش‌وند مسیر /lang/ (مثلاً example.com/de/) یا زیر دامنه زبان (مثلاً de.example.com) استفاده می‌کنند، بسته به تنظیم ساختار URL در زیر.','The SEO → Compatibility tab shows the live detection status and explains exactly what LF is doing for each feature area.'=>'زبانه SEO → سازگاری وضعیت تشخیص زنده را نشان می‌دهد و دقیقاً توضیح می‌دهد که LF برای هر حوزه ویژگی چه کاری انجام می‌دهد.','The share URL always reflects the current page — no manual URL entry needed. The linguaforge_social_share_url filter lets you override the resolved URL for any service.'=>'آدرس URL اشتراک همیشه بازتاب دهنده صفحه فعلی است — نیاز به وارد کردن دستی URL نیست. فیلتر linguaforge_social_share_url به شما امکان می‌دهد URL حل شده را برای هر سرویس جایگزین کنید.','The sitemap is announced in robots.txt automatically. All major search engines — Google, Bing, Yandex — discover it from robots.txt. No manual submission is required.'=>'نقشه سایت به طور خودکار در robots.txt اعلام می‌شود. تمام موتورهای جستجوی اصلی — گوگل، بینگ، یاندکس — آن را از robots.txt کشف می‌کنند. نیاز به ارسال دستی نیست.','The source page has no footnotes.'=>'صفحه منبع پاورقی ندارد.','The upload failed — please try again.'=>'آپلود ناموفق بود — لطفاً دوباره تلاش کنید.','The WordPress core sitemap lists all your content URLs. The LF sitemap tells search engines how language versions relate to each other via xhtml:link hreflang alternates. Submit both to Google Search Console for full coverage.'=>'نقشه سایت هسته وردپرس تمام آدرس‌های محتوا شما را فهرست می‌کند. نقشه سایت LF به موتورهای جستجو نشان می‌دهد که نسخه‌های زبانی چگونه به یکدیگر مرتبط هستند، از طریق تگ‌های xhtml:link hreflang. هر دو را برای پوشش کامل به کنسول جستجوی گوگل ارسال کنید.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'این پاورقی‌ها از صفحه منبع آمده‌اند و فقط برای مرجع نشان داده می‌شوند. آنها را با استفاده از ویرایشگر بلوک به این صفحه اضافه کنید.','This is the source page. Footnotes are edited directly in the block editor.'=>'این صفحه منبع است. پاورقی‌ها مستقیماً در ویرایشگر بلوک ویرایش می‌شوند.','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'این کلید در حال حاضر توسط سرور %s تامین می‌شود و نمی‌توان آن را در اینجا حذف کرد. کلید جدیدی در بالا وارد کنید تا با مقدار پایگاه داده جایگزین شود.','This language is protected and cannot be uninstalled.'=>'این زبان محافظت شده است و نمی‌توان آن را حذف نصب کرد.','This language matches the WordPress instance locale and cannot be uninstalled.'=>'این زبان با منطقه محلی نمونه وردپرس مطابقت دارد و نمی‌توان آن را حذف نصب کرد.','Tip: to reset a model to the built-in default, clear the field and save.'=>'نکته: برای بازنشانی یک مدل به مقدار پیش‌فرض داخلی، فیلد را پاک کنید و ذخیره کنید.','Title'=>'عنوان','Title is %1$d chars — aim for %2$d–%3$d.'=>'عنوان %1$d کاراکتر است — هدف برای %2$d–%3$d است.','Title is %1$d chars — may be truncated in SERPs (aim for %2$d–%3$d).'=>'عنوان %1$d کاراکتر است — ممکن است در نتایج جستجو کوتاه شود (هدف %2$d–%3$d).','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'برای استفاده از یک راز رمزگذاری سفارشی (به جای مقدار مشتق شده wp_salt)، این را به wp-config.php اضافه کنید:','Today'=>'امروز','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are excluded so they don\'t skew the totals.'=>'مصرف توکن بر اساس ویژگی، ارائه‌دهنده و مدل جمع‌آوری می‌شود. در هر تماس موفق AI ثبت می‌شود؛ پینگ‌های آزمایش اتصال استثنا شده‌اند تا بر مجموع تأثیر نگذارند.','Tone'=>'لحن','tone'=>'لحن','Tone:'=>'لحن:','Too many AI requests. Please retry in %d seconds.'=>'درخواست‌های هوش مصنوعی بیش از حد است. لطفاً در %d ثانیه مجدداً تلاش کنید.','Total'=>'کل','Total tokens'=>'کل توکن‌ها','Translate'=>'ترجمه','Translate / Revise'=>'ترجمه / بازنگری','Translate / Revise block'=>'بازنگری بلوک ترجمه','Translate all'=>'ترجمه همه','Translate chunk'=>'ترجمه بخش','Translate Content'=>'ترجمه محتوا','Translate missing'=>'ترجمه‌های مفقود','Translate page…'=>'در حال ترجمه صفحه…','Translated content'=>'محتوای ترجمه شده','Translated Names'=>'نام‌های ترجمه شده','Translated title'=>'عنوان ترجمه شده','Translated to:'=>'ترجمه شده به:','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'ترجمه شد. بازبینی در ویرایشگر سایت — لینک‌های داخلی، آدرس‌های ناوبری و نامک‌های قالب به‌طور خودکار به‌روزرسانی نمی‌شوند.','Translating…'=>'در حال ترجمه…','Translation'=>'ترجمه','Translation Caching'=>'کش کردن ترجمه','Translation found but permalink could not be generated'=>'ترجمه پیدا شد اما لینک دائمی ساخته نشد','Translation Limits'=>'محدودیت‌های ترجمه','Translation Limits & Behavior'=>'محدودیت‌ها و رفتارهای ترجمه','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'محدودیت‌های ترجمه: کنترل کنید کدام نقش‌های کاربری می‌توانند ترجمه هوشمند را فعال کنند و بودجه توکن ماهانه تعیین کنید. تجاوز از بودجه، تماس‌های هوشمند را تا ریست ماه متوقف می‌کند.','Translation Memory'=>'حافظه ترجمه','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'حافظه ترجمه نتایج هوشمند را بر اساس هش محتوا، جفت زبان، ارائه‌دهنده و مدل کش می‌کند. ویرایش یک پست، ورودی کش را نامعتبر می‌کند تا درخواست ترجمه بعدی نتیجه‌ای تازه دریافت کند.','Translation Memory cleared. %d cached block was removed.'=>'حافظه ترجمه پاک شد. %d بلوک کش شده حذف شد.' . "\0" . 'حافظه ترجمه پاک شد. %d بلوک کش شده حذف شدند.','Translation Memory: stores the full translated post per content hash. Clear it when you want to force a retranslation of all posts regardless of whether their content changed.'=>'حافظه ترجمه: هر پست ترجمه‌شده کامل را بر اساس هش محتوا ذخیره می‌کند. آن را پاک کنید زمانی که می‌خواهید ترجمه مجدد همه پست‌ها را بدون توجه به تغییر محتوا انجام دهید.','Translation workflow'=>'روند کاری ترجمه','Translation, Content Generator'=>'ترجمه، تولید محتوا','Treat H2 as H1 equivalent'=>'در نظر گرفتن H2 به عنوان معادل H1','Type'=>'نوع','Uli Hake'=>'اولی هاکه','Uninstall %s'=>'حذف نصب %s','Uninstall Behaviour'=>'حالت حذف افزونه','Uninstall setting saved.'=>'تنظیمات حذف ذخیره شد.','unknown error'=>'خطای ناشناخته','Unknown provider.'=>'ارائه‌دهنده ناشناخته.','Unknown search engine.'=>'موتور جستجوی ناشناخته.','Unlike hreflang — where LF always overrides other plugins because they cannot know your multilingual configuration — Open Graph is different: Yoast, Rank Math, and similar plugins already output correct OG tags for your content. Duplicating them adds no value. In auto mode, LF detects active SEO plugins and adds only what they cannot provide: og:locale (current language) and og:locale:alternate (all other configured languages).'=>'بر خلاف hreflang — که در آن LF همیشه بر سایر پلاگین‌ها اولویت دارد چون نمی‌توانند پیکربندی چندزبانه شما را بدانند — Open Graph متفاوت است: Yoast، Rank Math و پلاگین‌های مشابه در حال حاضر تگ‌های OG صحیح برای محتوای شما را خروجی می‌دهند. تکرار آن‌ها ارزش افزوده‌ای ندارد. در حالت خودکار، LF پلاگین‌های SEO فعال را تشخیص می‌دهد و فقط آنچه را که نمی‌توانند فراهم کنند، اضافه می‌کند: og:locale (زبان فعلی) و og:locale:alternate (تمام زبان‌های پیکربندی شده دیگر).','Up'=>'بالا','Upload .mo file'=>'آپلود فایل .mo','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'آپلود فایل‌های .mo کامپایل شده برای جایگزینی رشته‌های پلاگین‌های شخص ثالث برای زبان‌های خاص — برای مثال، ترجمه سفارشی ویک‌بک‌ینگ که به جای "اتاق" از "آپارتمان" استفاده می‌کند. فایل‌ها باید مطابق با قاعده نام‌گذاری وردپرس باشند: {textdomain}-{locale}.mo (مثلاً vikbooking-ca.mo). آنها در پوشه آپلود ذخیره می‌شوند و در بروزرسانی‌های پلاگین باقی می‌مانند.','Upload Override'=>'آپلود جایگزین','URL could not be mapped to a post — check the link target exists'=>'آدرس URL نمی‌تواند به پست نگاشت شود — هدف لینک وجود دارد را بررسی کنید','URL structure'=>'ساختار URL','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'ساختار URL: حالت پیشوند مسیر (example.com/de/) نیاز به تغییر سرور ندارد. حالت زیر دامنه (de.example.com) نیاز به رکورد DNS چندگانه، گواهینامه SSL چندگانه و تغییر در پیکربندی سرور وب دارد — راهنمای راه‌اندازی سرور را ببینید.','URL to enter'=>'آدرس URL وارد کنید','Use native share when available; fall back to clipboard copy. Recommended default for "Share" buttons.'=>'وقتی در دسترس است، از اشتراک بومی استفاده کنید؛ در غیر این صورت، به کپی کردن در کلیپ‌بورد برگردید. پیشنهاد شده برای دکمه‌های "اشتراک‌گذاری".','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'از برگه‌های بالای این صفحه برای پیکربندی هر بخش استفاده کنید. تغییرات در برگه روتر بلافاصله اعمال می‌شود؛ تغییرات در کلیدهای هوشمند و تنظیمات مدل، برای درخواست بعدی هوشمند اعمال می‌شود.','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'جدول اصطلاحات مدیریت‌شده توسط کاربر بر اساس هر جفت زبان. ورودی‌ها به درخواست سیستم ترجمه افزوده می‌شوند تا هوش مصنوعی از اصطلاحات ترجیحی به طور مداوم استفاده کند — حیاتی برای واژگان حوزه ("kWp"، "PPA"، "نقطه اتصال")، نام‌های تجاری که نباید ترجمه شوند، و عبارات استاندارد قانونی. هر دو فیلد زبان اختیاری است: «زبان مبدا» را خالی بگذارید تا ورودی در هر صورت اعمال شود؛ «زبان هدف» را خالی بگذارید تا در تمام زبان‌های هدف به طور همزمان اعمال شود.','Using custom meta description.'=>'استفاده از توضیحات متا سفارشی.','Using LF AI meta description.'=>'استفاده از متا توضیحات AI LF.','Value source'=>'منبع مقدار','View'=>'مشاهده','View built-in default'=>'مشاهده پیش‌فرض داخلی','View current robots.txt'=>'مشاهده فایل robots.txt فعلی','View details'=>'جزئیات را مشاهده کنید','View Lingua Forge details'=>'جزئیات Lingua Forge را مشاهده کنید','Visit plugin site'=>'به سایت پلاگین مراجعه کنید','Warning:'=>'هشدار:','WebSite'=>'وب‌سایت','WebSite — front page / blog index'=>'وب‌سایت — صفحه اصلی / فهرست وبلاگ','What LF provides — and collision avoidance'=>'آنچه LF ارائه می‌دهد — و جلوگیری از تصادم','What LF provides: hreflang tags for every configured language, Open Graph and Twitter Card tags with og:locale and og:locale:alternate, Schema.org JSON-LD with inLanguage annotations, and a dedicated multilingual sitemap at /lf-sitemap.xml with xhtml:link alternate entries for all translation groups.'=>'آنچه LF ارائه می‌دهد: برچسب‌های hreflang برای هر زبان پیکربندی شده، برچسب‌های Open Graph و Twitter Card با og:locale و og:locale:alternate، JSON-LD Schema.org با حاشیه‌نویسی‌های inLanguage، و یک نقشه سایت چندزبانه اختصاصی در /lf-sitemap.xml با ورودی‌های xhtml:link alternate برای تمام گروه‌های ترجمه.','When another SEO plugin is installed'=>'وقتی پلاگین SEO دیگری نصب شده است','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'وقتی لاگ‌گیری اشکال‌زدایی فعال است (از طریق سوئیچ زیر یا با تعریف LINGUAFORGE_AI_DEBUG در wp-config.php)، ویژگی‌های ترجمه و ترجمه قالب FSE، درخواست‌ها و پاسخ‌های هوش مصنوعی خام خود را برای رفع اشکال روی دیسک می‌نویسند. از این بخش برای نظارت بر آن خروجی استفاده کنید و پس از دریافت نیازتان، آن را پاک کنید — فایل‌ها می‌توانند در صفحات بزرگ سریع رشد کنند. مسیر دایرکتوری مقصد را از طریق فیلتر linguaforge_debug_dir پیکربندی کنید.','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'وقتی فعال باشد، بازدیدکنندگان اولین بار که کوکی زبان ندارند و پیشوند زبان در URL نیست، به نزدیک‌ترین نسخه زبان مطابقت داده می‌شوند. این انتقال در صورت عدم تطابق زبان ترجیحی مرورگر با زبان‌های فعال، انجام نمی‌شود. پس از انتخاب زبان توسط بازدیدکننده از طریق سوئیچر، کوکی اولویت دارد و هدر مرورگر در بازدیدهای بعدی نادیده گرفته می‌شود.','When enabled, Lingua Forge outputs the following additional meta tags on product pages: og:type=product, og:price:amount, og:price:currency, og:availability, and their product: namespace equivalents used by Facebook Catalog.'=>'وقتی فعال است، LF برگه‌های محصول، برچسب‌های متا اضافی مانند og:type=product، og:price:amount، og:price:currency، og:availability و معادل‌های namespace محصول را در خروجی می‌دهد که توسط Facebook Catalog استفاده می‌شود.','When enabled, the sitemap URL is announced in robots.txt automatically and the cache is refreshed when translated content is saved.'=>'وقتی فعال است، آدرس URL نقشه سایت به طور خودکار در robots.txt اعلام می‌شود و کش هنگام ذخیره محتوای ترجمه شده تازه می‌شود.','When Yoast SEO, Rank Math, All in One SEO, or SEOPress is active, Lingua Forge automatically suppresses their hreflang output via filter. General SEO plugins produce hreflang based on a single-language URL structure and cannot account for your multilingual routing configuration; LF\'s output is always correct.'=>'وقتی Yoast SEO، Rank Math، All in One SEO یا SEOPress فعال است، LF به طور خودکار خروجی hreflang آن‌ها را از طریق فیلتر سرکوب می‌کند. پلاگین‌های SEO عمومی بر اساس ساختار URL تک‌زبانه hreflang تولید می‌کنند و نمی‌توانند پیکربندی مسیر چندزبانه شما را در نظر بگیرند؛ خروجی LF همیشه صحیح است.','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'کدام سطح مدل برای ترجمه صفحه کامل استفاده شود. کیفیت از مدلی که در جدول مدل‌ها بالا پیکربندی شده است، استفاده می‌کند و برای ترجمه دقیق و بلندمدت توصیه می‌شود. فقط در صورت اولویت سرعت یا هزینه و محتوای کوتاه، به سبک سبک تغییر دهید.','While active, the mu-plugin handles the base OG set and LF emits locale tags only (auto mode). Removing it switches LF to full OG mode automatically.'=>'در حالی که فعال است، این ماژول پایه OG را مدیریت می‌کند و LF فقط برچسب‌های منطقه‌ای (در حالت خودکار) را می‌افزاید. حذف آن، LF را به حالت کامل OG به طور خودکار تغییر می‌دهد.','WooCommerce'=>'ووکامرس','WooCommerce product price'=>'قیمت محصول ووکامرس','WooCommerce SEO settings saved.'=>'تنظیمات SEO ووکامرس ذخیره شد.','WooCommerce store currency'=>'ارز فروشگاه ووکامرس','Word count'=>'تعداد کلمات','WP core canonical active (hreflang disabled)'=>'کانال اصلی WP فعال است (hreflang غیرفعال است)','WP-CLI reference'=>'مرجع WP-CLI','Write AI prompts and responses to disk for troubleshooting'=>'نوشتن درخواست‌ها و پاسخ‌های هوش مصنوعی روی دیسک برای رفع اشکال','XML Sitemap'=>'نقشه سایت XML','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'شما همچنین می‌توانید کلیدها را به عنوان ثوابت یا متغیرهای محیطی تعریف کنید (مثلاً در wp-config.php). این منابع به طور خودکار به عنوان جایگزین زمانی که کلید پایگاه داده ذخیره نشده باشد، استفاده می‌شوند.','You do not have permission to manage these settings.'=>'شما مجاز به مدیریت این تنظیمات نیستید.','You do not have permission to read this post.'=>'شما مجاز به خواندن این پست نیستید.','{n} stale path(s)'=>'{n} مسیر منقضی شده','~%d min read'=>'~%d دقیقه مطالعه' . "\0" . '~%d دقیقه مطالعه','— Any source language —'=>'— هر زبان منبع —','— Any target language —'=>'— هر زبان هدف —','— Any target —'=>'— هر هدف —','— Any —'=>'— هر —','— auto-detect —'=>'— تشخیص خودکار —','— Deferred to plugin'=>'— به پلاگین واگذار شد','— Disabled'=>'— غیرفعال شد','— Not detected'=>'— شناسایی نشده','— select a language —'=>'— یک زبان را انتخاب کنید —','— toggle in Settings → Behavior.'=>'— سوئیچ در تنظیمات → رفتار.','← Back'=>'← بازگشت','↑ Detected from current post'=>'↑ تشخیص داده شده از پست فعلی','→ Locale tags only (manual setting)'=>'→ برچسب‌های منطقه‌ای فقط (تنظیم دستی)','→ Locale tags only — deferring base OG to plugin'=>'→ برچسب‌های منطقه‌ای فقط — پایه OG به پلاگین واگذار شده است','↺ Re-translate'=>'↺ ترجمه مجدد','↺ Refine'=>'↺ اصلاح','↺ Refresh'=>'↺ تازه‌سازی','↺ Refresh AI Analysis'=>'↺ بروزرسانی تحلیل هوش مصنوعی','↺ Refreshing…'=>'↺ در حال تازه‌سازی…','⚠ Borderline'=>'⚠ مرزی','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ پست‌های <strong>{lang}</strong> یافت نشد. مطمئن شوید که تمام پست‌های ترجمه شده، متای زبان خود را بر روی <strong>{lang}</strong> تنظیم کرده‌اند.','⚠ No changes'=>'⚠ هیچ تغییری','⚠ No changes — re-scan?'=>'⚠ هیچ تغییری — اسکن مجدد؟','✅ Fixed ({n})'=>'✅ اصلاح شد ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ هیچ لینک شکسته یا ناسازگاری قالب برای <strong>{lang}</strong> یافت نشد. <strong>{scanned}</strong> پست و صفحه اسکن شده — همه بررسی‌ها موفق بودند. لینک‌های قسمت قالب (هدر، فوتر، سایدبار) در اینجا شامل نمی‌شود — برای بررسی جداگانه از دکمه اصلاح قسمت‌های قالب استفاده کنید.','✅ Template fixed'=>'✅ قالب اصلاح شد','✓ %s notified successfully.'=>'✓ %s با موفقیت اطلاع‌رسانی شد.','✓ Active'=>'✓ فعال','✓ Active at /lf-sitemap.xml'=>'✓ فعال در /lf-sitemap.xml','✓ Active — %d URL entry with language alternates'=>'✓ فعال — %d ورودی URL با جایگزین‌های زبان' . "\0" . '✓ فعال — %d ورودی URL با جایگزین‌های زبان','✓ Active — full OG + Twitter Cards'=>'✓ فعال — OG کامل + کارت‌های توییتر','✓ Active — locale tags only (og:locale, og:locale:alternate)'=>'✓ فعال — برچسب‌های منطقه‌ای فقط (og:locale، og:locale:alternate)','✓ All parts created.'=>'✓ همه قسمت‌ها ایجاد شدند.','✓ All templates created.'=>'✓ همه قالب‌ها ایجاد شدند.','✓ All translated.'=>'✓ همه ترجمه شدند.','✓ Configured'=>'✓ پیکربندی شده','✓ Connection OK'=>'✓ اتصال برقرار است','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ محتوا تولید شد — برای بازبینی، اصلاح و اعمال، پنجره را ببینید.','✓ Done'=>'✓ انجام شد','✓ Enabled'=>'✓ فعال شده','✓ Good length'=>'✓ طول مناسب','✓ Hreflang active'=>'✓ فعال بودن Hreflang','✓ In safe storage'=>'✓ در ذخیره‌سازی امن','✓ Language installed.'=>'✓ زبان نصب شد.','✓ LF outputs'=>'✓ خروجی‌های LF','✓ LF outputs Article / WebPage / WebSite'=>'✓ خروجی‌های LF مقاله / صفحه وب / وب‌سایت','✓ LF outputs full OG + Twitter Cards'=>'✓ فعال — OG کامل + کارت‌های توییتر','✓ LF outputs — plugin hreflang suppressed'=>'✓ خروجی‌های LF — پلاگین hreflang سرکوب شده است','✓ Links fixed.'=>'✓ لینک‌ها اصلاح شدند.','✓ Nav refs fixed.'=>'✓ ارجاعات ناوبری اصلاح شدند.','✓ Parts fixed.'=>'✓ قسمت‌ها اصلاح شدند.','✓ Pattern translated.'=>'✓ الگو ترجمه شد.','✓ Physical robots.txt found. LF\'s Sitemap directive is present.'=>'✓ فایل robots.txt فیزیکی پیدا شد. دستورالعمل سایت‌مپ LF موجود است.','✓ Refined — review the updated draft above.'=>'✓ اصلاح شد — پیش‌نویس به‌روزرسانی شده را بررسی کنید.','✓ Translation saved'=>'✓ ترجمه ذخیره شد','✓ WP core canonical removed'=>'✓ canonical هسته WP حذف شد','✗ %s ping failed. The sitemap URL is still announced in robots.txt — the search engine will discover it on its next crawl.'=>'✗ پینگ %s ناموفق بود. آدرس سایت‌مپ هنوز در robots.txt اعلام شده است — موتور جستجو در بازدید بعدی آن را کشف خواهد کرد.','✗ Disabled'=>'✗ غیرفعال شده','✗ Error:'=>'✗ خطا:','✗ Failed:'=>'✗ شکست خورد:','✗ Not configured'=>'✗ پیکربندی نشده','✗ Too long'=>'✗ خیلی بلند','✗ Too short'=>'✗ خیلی کوتاه','❌ Failed'=>'❌ شکست خورد','📄 Wrong template'=>'📄 قالب نادرست','📍 Stale path (page moved)'=>'📍 مسیر منقضی شده (صفحه جابه‌جا شده)']];
